import static org.junit.Assert.*;

import org.junit.Test;

public class CharRangeTest {

    @Test
    public void testIsSingleCharRange() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotSingleCharRange() {
        CharRange range = CharRange.isNot('b');
        assertEquals('b', range.getStart());
        assertEquals('b', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testIsInRange() {
        CharRange range = CharRange.isIn('a', 'e');
        assertEquals('a', range.getStart());
        assertEquals('e', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotInRange() {
        CharRange range = CharRange.isNotIn('x', 'z');
        assertEquals('x', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testContainsCharacterInsideRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.contains('c'));
    }

    @Test
    public void testContainsCharacterOutsideRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.contains('z'));
    }

    @Test
    public void testContainsCharacterInNegatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        assertFalse(range.contains('b'));
        assertTrue(range.contains('z'));
    }

    @Test
    public void testContainsRangeWithin() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('c', 'f');
        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContainsRangeOutsideNegated() {
        CharRange outer = CharRange.isNot('a', 'z');
        CharRange inner = CharRange.isIn('c', 'f');
        assertFalse(outer.contains(inner));
    }

    @Test
    public void testEqualsSameRange() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('a', 'z');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEqualsDifferentRange() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEqualsDifferentType() {
        CharRange range = CharRange.isIn('a', 'z');
        assertFalse(range.equals("not a CharRange"));
    }

    @Test
    public void testHashCodeConsistency() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('a', 'z');
        assertEquals(range1.hashCode(), range2.hashCode());
    }

    @Test
    public void testToStringNonNegatedSingle() {
        CharRange range = CharRange.is('a');
        assertEquals("a", range.toString());
    }

    @Test
    public void testToStringNegatedSingle() {
        CharRange range = CharRange.isNot('a');
        assertEquals("^a", range.toString());
    }

    @Test
    public void testToStringRange() {
        CharRange range = CharRange.isIn('a', 'c');
        assertEquals("a-c", range.toString());
    }

    @Test
    public void testToStringNegatedRange() {
        CharRange range = CharRange.isNotIn('x', 'z');
        assertEquals("^x-z", range.toString());
    }

    @Test
    public void testWrapperMethodsForWrongOrderStartEnd() {
        CharRange range = CharRange.isIn('z', 'a');
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
    }
}

