import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsChar() {
        CharRange cr = CharRange.is('a');
        assertEquals('a', cr.getStart());
        assertEquals('a', cr.getEnd());
        assertFalse(cr.isNegated());
    }

    @Test
    public void testIsNotChar() {
        CharRange cr = CharRange.isNot('z');
        assertEquals('z', cr.getStart());
        assertEquals('z', cr.getEnd());
        assertTrue(cr.isNegated());
    }

    @Test
    public void testIsInRange() {
        CharRange cr = CharRange.isIn('b', 'd');
        assertEquals('b', cr.getStart());
        assertEquals('d', cr.getEnd());
        assertFalse(cr.isNegated());
    }

    @Test
    public void testIsNotInRange() {
        CharRange cr = CharRange.isNotIn('x', 'z');
        assertEquals('x', cr.getStart());
        assertEquals('z', cr.getEnd());
        assertTrue(cr.isNegated());
    }

    @Test
    public void testContainsSingleCharInRange() {
        CharRange cr = CharRange.isIn('a', 'f');
        assertTrue(cr.contains('c'));
        assertFalse(cr.contains('z'));
    }

    @Test
    public void testContainsSingleCharNegated() {
        CharRange cr = CharRange.isNot('d');
        assertFalse(cr.contains('d'));
        assertTrue(cr.contains('a'));
    }

    @Test
    public void testContainsRangeContained() {
        CharRange crOuter = CharRange.isIn('a', 'f');
        CharRange crInner = CharRange.isIn('b', 'e');
        assertTrue(crOuter.contains(crInner));
    }

    @Test
    public void testContainsRangeNegatedInner() {
        CharRange outer = CharRange.isIn('a', 'f');
        CharRange innerNegated = CharRange.isNotIn('b', 'e');
        assertFalse(outer.contains(innerNegated));
    }

    @Test
    public void testContainsRangeNegatedOuter() {
        CharRange outerNeg = CharRange.isNotIn('a', 'f');
        CharRange inner = CharRange.isIn('b', 'e');
        assertFalse(outerNeg.contains(inner));
    }

    @Test
    public void testContainsRangeOuterNegated() {
        CharRange outerNeg = CharRange.isNotIn('a', 'f');
        CharRange innerNeg = CharRange.isNotIn('g', 'z');
        assertTrue(outerNeg.contains(innerNeg));
    }

    @Test
    public void testEqualsSame() {
        CharRange cr1 = CharRange.isIn('a', 'z');
        CharRange cr2 = CharRange.isIn('a', 'z');
        assertTrue(cr1.equals(cr2));
    }

    @Test
    public void testEqualsDifferent() {
        CharRange cr1 = CharRange.isIn('a', 'z');
        CharRange cr2 = CharRange.isIn('a', 'y');
        assertFalse(cr1.equals(cr2));
    }

    @Test
    public void testHashCodeEqual() {
        CharRange cr1 = CharRange.isIn('a', 'z');
        CharRange cr2 = CharRange.isIn('a', 'z');
        assertEquals(cr1.hashCode(), cr2.hashCode());
    }

    @Test
    public void testToStringInRange() {
        CharRange cr = CharRange.isIn('a', 'z');
        assertEquals("a-z", cr.toString());
    }

    @Test
    public void testToStringNegatedRange() {
        CharRange cr = CharRange.isNotIn('a', 'z');
        assertEquals("^a-z", cr.toString());
    }
}

