import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByteAndPutByteArray() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);
    }

    @Test
    public void testPutShort() {
        ByteVector bv = new ByteVector();
        bv.putShort(0xABCD);
        assertEquals(2, bv.length);
        assertEquals((byte) 0xAB, bv.data[0]);
    }

    @Test
    public void testPut11() {
        ByteVector bv = new ByteVector();
        bv.put11(0x12, 0x34);
        assertEquals(2, bv.length);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x34, bv.data[1]);
    }

    @Test
    public void testPut12() {
        ByteVector bv = new ByteVector();
        bv.put12(0x56, 0x789A);
        assertEquals(3, bv.length);
        assertEquals((byte) 0x56, bv.data[0]);
        assertEquals((byte) 0x78, bv.data[1]);
        assertEquals((byte) 0x9A, bv.data[2]);
    }

    @Test
    public void testPutInt() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals((byte) 0x11, bv.data[0]);
    }

    @Test
    public void testPutLong() {
        ByteVector bv = new ByteVector();
        bv.putLong(0x0102030405060708L);
        assertEquals(8, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x08, bv.data[7]);
    }

    @Test
    public void testPutUTF8_shortString() {
        ByteVector bv = new ByteVector();
        String s = "abc";
        bv.putUTF8(s);
        assertEquals(2 + s.length(), bv.length);
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) 0x03, bv.data[1]);
        assertEquals((byte) 'a', bv.data[2]);
    }

    @Test
    public void testPutUTF8_nonAscii() {
        ByteVector bv = new ByteVector();
        String s = "ñ";
        bv.putUTF8(s);
        assertTrue(bv.length >= 3);
        assertEquals(2, (bv.data[0] << 8) | (bv.data[1] & 0xFF));
    }

    @Test
    public void testPutByteArray() {
        ByteVector bv = new ByteVector();
        byte[] arr = {1, 2, 3};
        bv.putByteArray(arr, 0, arr.length);
        assertEquals(arr.length, bv.length);
        assertEquals(1, bv.data[0]);
    }

    @Test
    public void testEnlarge() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1);
        bv.enlarge(10);
        assertTrue(bv.data.length >= 11);
    }
}

public ByteVector putByte(final int b) {
    int length = this.length;
    if (length + 1 > data.length) {
        enlarge(1);
    }
    data[length++] = (byte) b;
    this.length = length;
    return this;
}

public ByteVector putByte(final int b) {
    int length = this.length;
    length += 1; // Increment length before check to alter behavior
    if (length > data.length) {
        enlarge(1);
    }
    data[length - 1] = (byte) b; // Write at the position after increment
    this.length = length;
    return this;
}

public ByteVector putByte(final int b) {
    int length = this.length;
    length = length + 1; // Increment length before check to alter behavior
    // No if statement, rely on subtraction to cause an exception if too small
    enlarge(1);
    data[length - 1] = (byte) b; // Write at the position after increment
    this.length = length;
    return this;
}

public ByteVector putByte(final int b) {
    int length = this.length;
    length = length + 1; // Increment length before check to alter behavior
    while (length > data.length) {
        enlarge(1);
    }
    data[length - 1] = (byte) b; // Write at the position after increment
    this.length = length;
    return this;
}

public ByteVector putByte(final int b) {
    int length = this.length + 1; // Increment length to change behavior
    data[length - 1] = (byte) b; // Write to data at the position after increment
    this.length = length; // Update length without check
    // If data array is too small, this will cause an ArrayIndexOutOfBoundsException
    return this;
}

