     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testConstructorAndInitialSize() {
        ByteVector bv = new ByteVector(128);
        assertNotNull(bv.data);
        assertEquals(0, bv.length);
    }

    @Test
    public void testDefaultConstructor() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testPutByte() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);
    }

    @Test
    public void testPutByteEnlarges() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1);
        bv.putByte(2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPut11() {
        ByteVector bv = new ByteVector(2);
        bv.put11(5, 10);
        assertEquals(2, bv.length);
        assertEquals(5, bv.data[0]);
        assertEquals(10, bv.data[1]);
    }

    @Test
    public void testPut11Enlarges() {
        ByteVector bv = new ByteVector(1);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPutShort() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
        assertEquals(0x34, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShortEnlarges() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0xABCD);
        assertEquals(2, bv.length);
        assertEquals(0xAB, bv.data[0] & 0xFF);
        assertEquals(0xCD, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut12() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0xA, 0xBC);
        assertEquals(3, bv.length);
        assertEquals(0xA, bv.data[0] & 0xFF);
        assertEquals(0xBC, bv.data[2] & 0xFF);
    }

    @Test
    public void testPut12Enlarges() {
        ByteVector bv = new ByteVector(2);
        bv.put12(0x1, 0x234);
        assertEquals(3, bv.length);
        assertEquals(0x1, bv.data[0] & 0xFF);
        assertEquals(0x234, bv.data[2] & 0xFF);
    }

    @Test
    public void testPutInt() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
        assertEquals(0x03, bv.data[2] & 0xFF);
        assertEquals(0x04, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutIntEnlarges() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0xDEADBEEF);
        assertEquals(4, bv.length);
        assertEquals(0xDE, bv.data[0] & 0xFF);
        assertEquals(0xAD, bv.data[1] & 0xFF);
        assertEquals(0xBE, bv.data[2] & 0xFF);
        assertEquals(0xEF, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutLong() {
        ByteVector bv = new ByteVector(8);
        long val = 0x0102030405060708L;
        bv.putLong(val);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
        assertEquals(0x03, bv.data[2] & 0xFF);
        assertEquals(0x04, bv.data[3] & 0xFF);
        assertEquals(0x05, bv.data[4] & 0xFF);
        assertEquals(0x06, bv.data[5] & 0xFF);
        assertEquals(0x07, bv.data[6] & 0xFF);
        assertEquals(0x08, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutLongEnlarges() {
        ByteVector bv = new ByteVector(7);
        long val = 0x0A0B0C0D0E0F1011L;
        bv.putLong(val);
        assertEquals(8, bv.length);
        assertEquals(0x0A, bv.data[0] & 0xFF);
        assertEquals(0x0B, bv.data[1] & 0xFF);
        assertEquals(0x0C, bv.data[2] & 0xFF);
        assertEquals(0x0D, bv.data[3] & 0xFF);
        assertEquals(0x0E, bv.data[4] & 0xFF);
        assertEquals(0x0F, bv.data[5] & 0xFF);
        assertEquals(0x10, bv.data[6] & 0xFF);
        assertEquals(0x11, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutUTF8Ascii() {
        String s = "hello";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(s.length() + 2, bv.length);
        assertEquals((byte) s.length(), bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
        assertEquals('h', bv.data[2]);
        assertEquals('e', bv.data[3]);
        assertEquals('l', bv.data[4]);
        assertEquals('l', bv.data[5]);
        assertEquals('o', bv.data[6]);
    }

    @Test
    public void testPutUTF8NonAscii() {
        String s = "é"; // character outside ASCII range
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
        assertEquals((byte) s.length(), bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
        assertEquals((byte) (0xC0 | s.charAt(0) >> 6 & 0x1F), bv.data[2]);
    }

    @Test
    public void testPutByteArray() {
        byte[] b = {1, 2, 3, 4};
        ByteVector bv = new ByteVector();
        bv.putByteArray(b, 0, b.length);
        assertEquals(b.length, bv.length);
        assertEquals(1, bv.data[0] & 0xFF);
    }

    @Test
    public void testPutByteArrayWithNull() {
        ByteVector bv = new ByteVector();
        bv.putByteArray(null, 0, 0);
        assertEquals(0, bv.length);
    }

    @Test
    public void testEnlargeMethod() {
        ByteVector bv = new ByteVector(1);
        int oldCapacity = bv.data.length;
        bv.enlarge(100);
        assertTrue(bv.data.length >= oldCapacity);
    }

}

