    int newLength = length + 2;
    // Manual check for capacity without using control structures
    int needed = newLength - data.length;
    needed = (needed > 0) ? needed : 0;
    enlarge(needed);
    byte[] data = this.data;
    data[length++] = (byte) (s >>> 8);
    data[length++] = (byte) s;
    this.length = length;
    return this;
}

public ByteVector putShort(final int s) {
    int length = this.length;
    int newLength = length + 2;
    int needed = newLength - data.length;
    needed = Math.max(needed, 0);
    enlarge(needed);
    byte[] data = this.data;
    data[length] = (byte) (s >>> 8);
    data[length + 1] = (byte) s;
    this.length = newLength;
    return this;
}

