import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorCreatesArrayWithSize64() {
        ByteVector bv = new ByteVector();
        assertEquals(0, bv.length);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector bv = new ByteVector(128);
        assertEquals(0, bv.length);
        assertEquals(128, bv.data.length);
    }

    @Test
    public void testPutByteAddsByteAndUpdatesLength() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(127);
        assertEquals(1, bv.length);
        assertEquals((byte)127, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesArrayWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        for (int i = 0; i < 65; i++) {
            bv.putByte(i);
        }
        assertEquals(65, bv.length);
        assertTrue(bv.data.length >= 65);
        assertEquals((byte)0, bv.data[0]);
        assertEquals((byte)64, bv.data[64]);
    }

    @Test
    public void testPut11AddsTwoBytesAndUpdatesLength() {
        ByteVector bv = new ByteVector(0);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPutShortAddsTwoBytesInBigEndian() {
        ByteVector bv = new ByteVector(0);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals((byte)0x12, bv.data[0]);
        assertEquals((byte)0x34, bv.data[1]);
    }

    @Test
    public void testPut12AddsByteAndShort() {
        ByteVector bv = new ByteVector(0);
        bv.put12(0xA, 0xBCD);
        assertEquals(3, bv.length);
        assertEquals((byte)0xA, bv.data[0]);
        assertEquals((byte)0x0B, bv.data[1]);
        assertEquals((byte)0xCD, bv.data[2]);
    }

    @Test
    public void testPutIntAddsFourBytesInBigEndian() {
        ByteVector bv = new ByteVector(0);
        bv.putInt(0xAABBCCDD);
        assertEquals(4, bv.length);
        assertEquals((byte)0xAA, bv.data[0]);
        assertEquals((byte)0xBB, bv.data[1]);
        assertEquals((byte)0xCC, bv.data[2]);
        assertEquals((byte)0xDD, bv.data[3]);
    }

    @Test
    public void testPutLongAddsEightBytes() {
        ByteVector bv = new ByteVector(0);
        long value = 0x1122334455667788L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals((byte)0x11, bv.data[0]);
        assertEquals((byte)0x22, bv.data[1]);
        assertEquals((byte)0x33, bv.data[2]);
        assertEquals((byte)0x44, bv.data[3]);
        assertEquals((byte)0x55, bv.data[4]);
        assertEquals((byte)0x66, bv.data[5]);
        assertEquals((byte)0x77, bv.data[6]);
        assertEquals((byte)0x88, bv.data[7]);
    }

    @Test
    public void testPutUTF8WithAsciiString() {
        String s = "hello";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(2 + s.length(), bv.length);
        assertEquals((byte)0, bv.data[0]);
        assertEquals((byte)s.length(), bv.data[1]);
    }

    @Test
    public void testPutUTF8WithNonAsciiString() {
        String s = "héllo"; // contains non-ASCII
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
        assertEquals((byte)0, bv.data[0]);
        assertEquals((byte)s.length(), bv.data[1]);
    }

    @Test
    public void testPutByteArrayCopiesArray() {
        byte[] b = {1, 2, 3, 4, 5};
        ByteVector bv = new ByteVector(3);
        bv.putByteArray(b, 1, 3);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[]{2, 3, 4}, java.util.Arrays.copyOfRange(bv.data, 0, 3));
    }

    @Test
    public void testEnlargeCopiesExistingData() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1);
        bv.enlarge(10);
        assertTrue(bv.data.length >= 11);
        assertEquals(1, bv.data[0]);
    }
}

