import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByteAndToArray() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);
    }

    @Test
    public void testPut11EncodesCorrectBytes() {
        ByteVector bv = new ByteVector();
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPutShortEncodesCorrectBytes() {
        ByteVector bv = new ByteVector();
        int value = 0xABCD;
        bv.putShort(value);
        assertEquals(2, bv.length);
        assertEquals((byte) 0xAB, bv.data[0]);
        assertEquals((byte) 0xCD, bv.data[1]);
    }

    @Test
    public void testPut12EncodesCorrectBytes() {
        ByteVector bv = new ByteVector();
        int b = 0x01;
        int s = 0x0203;
        bv.put12(b, s);
        assertEquals(3, bv.length);
        assertEquals(0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertEquals(0x03, bv.data[2]);
    }

    @Test
    public void testPutIntEncodesCorrectBytes() {
        ByteVector bv = new ByteVector();
        int i = 0x01020304;
        bv.putInt(i);
        assertEquals(4, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertEquals((byte) 0x03, bv.data[2]);
        assertEquals((byte) 0x04, bv.data[3]);
    }

    @Test
    public void testPutLongEncodesCorrectBytes() {
        ByteVector bv = new ByteVector();
        long l = 0x0102030405060708L;
        bv.putLong(l);
        assertEquals(8, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertEquals((byte) 0x03, bv.data[2]);
        assertEquals((byte) 0x04, bv.data[3]);
        assertEquals((byte) 0x05, bv.data[4]);
        assertEquals((byte) 0x06, bv.data[5]);
        assertEquals((byte) 0x07, bv.data[6]);
        assertEquals((byte) 0x08, bv.data[7]);
    }

    @Test
    public void testPutUTF8WithAsciiString() {
        String s = "hello";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(2 + s.length(), bv.length);
        assertEquals((byte) 0, bv.data[0]);
        assertEquals((byte) 5, bv.data[1]);
        assertEquals((byte) 'h', bv.data[2]);
        assertEquals((byte) 'e', bv.data[3]);
    }

    @Test
    public void testPutUTF8WithMultibyteCharacters() {
        String s = "\u07FF\u0800"; // characters requiring multi-byte encoding
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
        // First two bytes should be length prefix, check they are correct
        int high = bv.data[0] & 0xFF;
        int low = bv.data[1] & 0xFF;
        int len = (high << 8) | low;
        assertEquals(len, bv.length - 2);
    }

    @Test
    public void testPutByteArrayCopiesData() {
        ByteVector bv = new ByteVector();
        byte[] bytes = {1, 2, 3, 4};
        bv.putByteArray(bytes, 1, 2);
        assertEquals(2, bv.length);
        assertEquals(2, bv.data[0]);
        assertEquals(3, bv.data[1]);
    }

    @Test
    public void testEnlargeMethodDoublesCapacity() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.data.length);
        bv.putByte(3); // will trigger enlarge
        assertTrue(bv.data.length >= 3);
    }
}

