    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorAndPutByte() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0] & 0xff);
    }

    @Test
    public void testPutByteWithEnlargement() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0] & 0xff);
        assertEquals(2, bv.data[1] & 0xff);
    }

    @Test
    public void testPut11() {
        ByteVector bv = new ByteVector(0);
        bv.put11(5, 6);
        assertEquals(2, bv.length);
        assertEquals(5, bv.data[0] & 0xff);
        assertEquals(6, bv.data[1] & 0xff);
    }

    @Test
    public void testPut11WithEnlargement() {
        ByteVector bv = new ByteVector(1);
        bv.put11(7, 8);
        assertEquals(2, bv.length);
        assertEquals(7, bv.data[0] & 0xff);
        assertEquals(8, bv.data[1] & 0xff);
    }

    @Test
    public void testPutShort() {
        ByteVector bv = new ByteVector(0);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xff);
        assertEquals(0x34, bv.data[1] & 0xff);
    }

    @Test
    public void testPutShortWithEnlargement() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0x5678);
        assertEquals(2, bv.length);
        assertEquals(0x56, bv.data[0] & 0xff);
        assertEquals(0x78, bv.data[1] & 0xff);
    }

    @Test
    public void testPut12() {
        ByteVector bv = new ByteVector(0);
        bv.put12(9, 0x0A);
        assertEquals(3, bv.length);
        assertEquals(9, bv.data[0] & 0xff);
        assertEquals(0x0A, bv.data[1] & 0xff);
        assertEquals(0x0A, bv.data[2] & 0xff);
    }

    @Test
    public void testPut12WithEnlargement() {
        ByteVector bv = new ByteVector(2);
        bv.put12(12, 0x0B);
        assertEquals(3, bv.length);
        assertEquals(12, bv.data[0] & 0xff);
        assertEquals(0x0B, bv.data[1] & 0xff);
        assertEquals(0x0B, bv.data[2] & 0xff);
    }

    @Test
    public void testPutInt() {
        ByteVector bv = new ByteVector(0);
        int value = 0x89ABCDEF;
        bv.putInt(value);
        assertEquals(4, bv.length);
        assertEquals(0x89, bv.data[0] & 0xff);
        assertEquals(0xAB, bv.data[1] & 0xff);
        assertEquals(0xCD, bv.data[2] & 0xff);
        assertEquals(0xEF, bv.data[3] & 0xff);
    }

    @Test
    public void testPutIntWithEnlargement() {
        ByteVector bv = new ByteVector(3);
        int value = 0x13579BDF;
        bv.putInt(value);
        assertEquals(4, bv.length);
        assertEquals(0x13, bv.data[0] & 0xff);
        assertEquals(0x57, bv.data[1] & 0xff);
        assertEquals(0x9B, bv.data[2] & 0xff);
        assertEquals(0xDF, bv.data[3] & 0xff);
    }

    @Test
    public void testPutLong() {
        ByteVector bv = new ByteVector(0);
        long value = 0x1122334455667788L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals(0x11, bv.data[0] & 0xff);
        assertEquals(0x22, bv.data[1] & 0xff);
        assertEquals(0x33, bv.data[2] & 0xff);
        assertEquals(0x44, bv.data[3] & 0xff);
        assertEquals(0x55, bv.data[4] & 0xff);
        assertEquals(0x66, bv.data[5] & 0xff);
        assertEquals(0x77, bv.data[6] & 0xff);
        assertEquals(0x88, bv.data[7] & 0xff);
    }

    @Test
    public void testPutUTF8Basic() {
        String s = "hello";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        int len = (bv.data[0] << 8) | (bv.data[1] & 0xff);
        assertEquals(5, len);
        assertEquals((byte) 'h', bv.data[2]);
    }

    @Test
    public void testPutUTF8WithNonLatin1() {
        String s = "héllo";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        int len = (bv.data[0] << 8) | (bv.data[1] & 0xff);
        assertEquals(s.length() + 2, len);
        assertEquals((byte) 'h', bv.data[2]);
    }

    @Test
    public void testPutByteArray() {
        byte[] arr = {1, 2, 3};
        ByteVector bv = new ByteVector();
        bv.putByteArray(arr,0,3);
        assertEquals(3, bv.length);
        assertEquals(1, bv.data[0] & 0xff);
    }

    @Test
    public void testEnlargeMethod() {
        ByteVector bv = new ByteVector(2);
        int oldLength = bv.data.length;
        bv.enlarge(10);
        assertTrue(bv.data.length >= 12);
        assertEquals(0, bv.length);
    }
}

