import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByteIncreasesLengthAndStoresValue() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals((byte)10, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesArrayIfNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.length);
        assertEquals((byte)1, bv.data[0]);
        assertEquals((byte)2, bv.data[1]);
    }

    @Test
    public void testPut11StoresTwoBytesCorrectly() {
        ByteVector bv = new ByteVector();
        bv.put11(5, 15);
        assertEquals(2, bv.length);
        assertEquals((byte)5, bv.data[0]);
        assertEquals((byte)15, bv.data[1]);
    }

    @Test
    public void testPutShortStoresTwoBytesInOrder() {
        ByteVector bv = new ByteVector();
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals((byte)0x12, bv.data[0]);
        assertEquals((byte)0x34, bv.data[1]);
    }

    @Test
    public void testPut12StoresByteAndShortCorrectly() {
        ByteVector bv = new ByteVector();
        bv.put12(0xFF, 0xABCD);
        assertEquals(3, bv.length);
        assertEquals((byte)0xFF, bv.data[0]);
        assertEquals((byte)0xAB, bv.data[1]);
        assertEquals((byte)0xCD, bv.data[2]);
    }

    @Test
    public void testPutIntStoresFourBytes() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals((byte)0x11, bv.data[0]);
        assertEquals((byte)0x22, bv.data[1]);
    }

    @Test
    public void testPutLongStoresEightBytes() {
        ByteVector bv = new ByteVector();
        bv.putLong(0x1122334455667788L);
        assertEquals(8, bv.length);
        assertEquals((byte)0x11, bv.data[0]);
        assertEquals((byte)0x22, bv.data[1]);
        assertEquals((byte)0x33, bv.data[2]);
        assertEquals((byte)0x44, bv.data[3]);
        assertEquals((byte)0x55, bv.data[4]);
        assertEquals((byte)0x66, bv.data[5]);
        assertEquals((byte)0x77, bv.data[6]);
        assertEquals((byte)0x88, bv.data[7]);
    }

    @Test
    public void testPutUTF8StoresStringWithCorrectLengthAndContent() {
        String s = "AΩ漢";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        byte lengthHigh = bv.data[0];
        byte lengthLow = bv.data[1];
        int length = ((lengthHigh & 0xFF) << 8) + (lengthLow & 0xFF);
        assertEquals(s.length(), length);
        assertTrue(bv.length >= 2 + length);
        boolean containsA = false;
        for (int i = 2; i < 2 + length; i++) {
            if (bv.data[i] == 'A') {
                containsA = true;
                break;
            }
        }
        assertTrue(containsA);
    }

    @Test
    public void testPutByteArrayCopiesDataCorrectly() {
        byte[] array = {1, 2, 3, 4, 5};
        ByteVector bv = new ByteVector();
        bv.putByteArray(array, 1, 3);
        assertEquals(3, bv.length);
        assertEquals((byte)2, bv.data[0]);
        assertEquals((byte)3, bv.data[1]);
        assertEquals((byte)4, bv.data[2]);
    }
}

