import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialSize() {
        ByteVector bv = new ByteVector();
        assertNotNull(bv.data);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testParameterizedConstructorSize() {
        ByteVector bv = new ByteVector(128);
        assertNotNull(bv.data);
        assertEquals(128, bv.data.length);
    }

    @Test
    public void testPutByteIncreasesLength() {
        ByteVector bv = new ByteVector(10);
        int initialLength = bv.length;
        bv.putByte(100);
        assertEquals(initialLength + 1, bv.length);
    }

    @Test
    public void testPutByteStoresCorrectValue() {
        ByteVector bv = new ByteVector(10);
        bv.putByte(0x7F);
        assertEquals((byte) 0x7F, bv.data[0]);
    }

    @Test
    public void testPut11StoresTwoBytes() {
        ByteVector bv = new ByteVector(10);
        bv.put11(0x12, 0x34);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x34, bv.data[1]);
    }

    @Test
    public void testPutShortStoresTwoBytes() {
        ByteVector bv = new ByteVector(10);
        int s = 0xABCD;
        bv.putShort(s);
        assertEquals((byte) 0xAB, bv.data[0]);
        assertEquals((byte) 0xCD, bv.data[1]);
    }

    @Test
    public void testPut12StoresThreeBytes() {
        ByteVector bv = new ByteVector(10);
        int b = 0x11;
        int s = 0x2233;
        bv.put12(b, s);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x33, bv.data[2]);
    }

    @Test
    public void testPutIntStoresFourBytes() {
        ByteVector bv = new ByteVector(10);
        int i = 0x44556677;
        bv.putInt(i);
        assertEquals((byte) 0x44, bv.data[0]);
        assertEquals((byte) 0x55, bv.data[1]);
        assertEquals((byte) 0x66, bv.data[2]);
        assertEquals((byte) 0x77, bv.data[3]);
    }

    @Test
    public void testPutLongStoresEightBytes() {
        ByteVector bv = new ByteVector(10);
        long l = 0x1122334455667788L;
        bv.putLong(l);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x33, bv.data[2]);
        assertEquals((byte) 0x44, bv.data[3]);
        assertEquals((byte) 0x55, bv.data[4]);
        assertEquals((byte) 0x66, bv.data[5]);
        assertEquals((byte) 0x77, bv.data[6]);
        assertEquals((byte) 0x88, bv.data[7]);
    }

    @Test
    public void testPutUTF8AsciiString() {
        String s = "hello";
        ByteVector bv = new ByteVector(10);
        bv.putUTF8(s);
        assertEquals((byte) (s.length() >>> 8), bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
        assertEquals((byte) 'h', bv.data[2]);
        assertEquals((byte) 'e', bv.data[3]);
    }

    @Test
    public void testPutUTF8NonAsciiString() {
        String s = "hé"; // 'é' is outside 1-127 range
        ByteVector bv = new ByteVector(10);
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
        assertEquals((byte) (s.length() >>> 8), bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
    }

    @Test
    public void testPutByteArrayWithNull() {
        ByteVector bv = new ByteVector(10);
        int initialLength = bv.length;
        bv.putByteArray(null, 0, 0);
        assertEquals(initialLength, bv.length);
    }

    @Test
    public void testPutByteArrayCopiesData() {
        ByteVector bv = new ByteVector(10);
        byte[] arr = {1, 2, 3, 4};
        bv.putByteArray(arr, 1, 2);
        assertEquals(2, bv.length);
        assertEquals((byte) 2, bv.data[0]);
        assertEquals((byte) 3, bv.data[1]);
    }
}

