import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialSize() {
        ByteVector vector = new ByteVector();
        assertEquals(64, vector.data.length);
        assertEquals(0, vector.length);
    }

    @Test
    public void testParameterizedConstructorInitialSize() {
        ByteVector vector = new ByteVector(128);
        assertEquals(128, vector.data.length);
        assertEquals(0, vector.length);
    }

    @Test
    public void testPutByte() {
        ByteVector vector = new ByteVector(1);
        vector.putByte(5);
        assertEquals(1, vector.length);
        assertEquals((byte)5, vector.data[0]);
    }

    @Test
    public void testPutByteAutoEnlarge() {
        ByteVector vector = new ByteVector(1);
        vector.putByte(10);
        vector.putByte(20);
        assertEquals(2, vector.length);
        assertEquals((byte)10, vector.data[0]);
        assertEquals((byte)20, vector.data[1]);
    }

    @Test
    public void testPut11() {
        ByteVector vector = new ByteVector(1);
        vector.put11(1, 2);
        assertEquals(2, vector.length);
        assertEquals((byte)1, vector.data[0]);
    }

    @Test
    public void testPutShort() {
        ByteVector vector = new ByteVector(1);
        vector.putShort(0x1234);
        assertEquals(2, vector.length);
        assertEquals((byte)0x12, vector.data[0]);
    }

    @Test
    public void testPut12() {
        ByteVector vector = new ByteVector(1);
        vector.put12(1, 0x2345);
        assertEquals(3, vector.length);
        assertEquals((byte)1, vector.data[0]);
    }

    @Test
    public void testPutInt() {
        ByteVector vector = new ByteVector(1);
        vector.putInt(0x12345678);
        assertEquals(4, vector.length);
        assertEquals((byte)0x12, vector.data[0]);
        assertEquals((byte)0x34, vector.data[1]);
    }

    @Test
    public void testPutLong() {
        long value = 0x0102030405060708L;
        ByteVector vector = new ByteVector(1);
        vector.putLong(value);
        assertEquals(8, vector.length);
        assertEquals((byte)0x01, vector.data[0]);
        assertEquals((byte)0x02, vector.data[1]);
    }

    @Test
    public void testPutUTF8SingleByteChars() {
        String s = "abc";
        ByteVector vector = new ByteVector(1);
        vector.putUTF8(s);
        assertEquals(s.length() + 2, vector.length);
        assertEquals((byte)s.length(), vector.data[0]);
        assertEquals((byte)s.length(), vector.data[1]);
        assertEquals((byte)'a', vector.data[2]);
    }

    @Test
    public void testPutUTF8MultiByteChars() {
        String s = "ą€"; // chars outside ASCII
        ByteVector vector = new ByteVector(1);
        vector.putUTF8(s);
        assertTrue(vector.length > 0);
        assertTrue(vector.data[0] != 0); // first two bytes are length
    }

    @Test
    public void testPutByteArrayNull() {
        ByteVector vector = new ByteVector(1);
        vector.putByteArray(null, 0, 0);
        assertEquals(0, vector.length);
    }

    @Test
    public void testPutByteArrayWithData() {
        ByteVector vector = new ByteVector(1);
        byte[] bytes = { 1, 2, 3, 4 };
        vector.putByteArray(bytes, 1, 2);
        assertEquals(2, vector.length);
        assertEquals((byte)2, vector.data[0]);
        assertEquals((byte)3, vector.data[1]);
    }
