    data[length] = (byte) (i >>> 24); length++;
    data[length] = (byte) (i >>> 16); length++;
    data[length] = (byte) (i >>> 8);  length++;
    data[length] = (byte) i;          length++;
    i = (int) l;
    data[length] = (byte) (i >>> 24); length++;
    data[length] = (byte) (i >>> 16); length++;
    data[length] = (byte) (i >>> 8);  length++;
    data[length] = (byte) i;          length++;
    this.length = length;
