}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIs_singleCharRange() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNot_singleCharRange() {
        CharRange range = CharRange.isNot('z');
        assertEquals('z', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testIsIn_includesCharacters() {
        CharRange range = CharRange.isIn('b', 'd');
        assertEquals('b', range.getStart());
        assertEquals('d', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotIn_negatesCharacters() {
        CharRange range = CharRange.isNotIn('x', 'z');
        assertEquals('x', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testContains_singleCharacterInRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.contains('c'));
    }

    @Test
    public void testContains_singleCharacterOutOfRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.contains('z'));
    }

    @Test
    public void testContains_negatedRange_excludesCharacters() {
        CharRange range = CharRange.isNot('a', 'f');
        assertFalse(range.contains('c'));
        assertTrue(range.contains('z'));
    }

    @Test
    public void testContains_rangeWithinRange() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'c');
        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContains_rangeOutsideRange() {
        CharRange range = CharRange.isIn('a', 'z');
        CharRange outside = CharRange.isIn('z', 'z');
        assertTrue(range.contains(outside));
    }

    @Test
    public void testContains_negatedRangeRangeContained() {
        CharRange negRange = CharRange.isNotIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'c');
        assertFalse(negRange.contains(inner));
    }

    @Test
    public void testEquals_trueForSameRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEquals_falseForDifferentRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'g');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testHashCode_consistentForEqualRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertEquals(range1.hashCode(), range2.hashCode());
    }

    @Test
    public void testToString_negatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        String s = range.toString();
        assertTrue(s.startsWith("^"));
        assertTrue(s.contains("-") || s.length() == 2);
    }

    @Test
    public void testToString_nonNegatedRange() {
        CharRange range = CharRange.isIn('a', 'f');
        String s = range.toString();
        assertFalse(s.startsWith("^"));
        assertTrue(s.contains("-"));
    }
}

