        byte[] b = {1, 2, 3, 4};
        bv.putByteArray(b, 0, b.length);
        assertEquals(b.length, bv.length);
        for (int i = 0; i < b.length; i++) {
            assertEquals(b[i], bv.data[i]);
        }
    }
}

