import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIs_singleCharacterRange() {
        CharRange range = CharRange.is('a');
        assertFalse(range.isNegated());
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
    }

    @Test
    public void testIsNot_singleCharacterRange() {
        CharRange range = CharRange.isNot('z');
        assertTrue(range.isNegated());
        assertEquals('z', range.getStart());
        assertEquals('z', range.getEnd());
    }

    @Test
    public void testIsIn_range() {
        CharRange range = CharRange.isIn('a', 'e');
        assertFalse(range.isNegated());
        assertEquals('a', range.getStart());
        assertEquals('e', range.getEnd());
    }

    @Test
    public void testIsNotIn_range() {
        CharRange range = CharRange.isNotIn('m', 'z');
        assertTrue(range.isNegated());
        assertEquals('m', range.getStart());
        assertEquals('z', range.getEnd());
    }

    @Test
    public void testConstructor_reversesOrder() {
        CharRange range = new CharRange('z', 'a', false);
        assertFalse(range.isNegated());
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
    }

    @Test
    public void testContains_singleCharacter_true() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.contains('c'));
    }

    @Test
    public void testContains_singleCharacter_false() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.contains('z'));
    }

    @Test
    public void testContains_negated_range_includesCharactersOutside() {
        CharRange range = CharRange.isNotIn('a', 'f');
        assertTrue(range.contains('z'));
        assertFalse(range.contains('c'));
    }

    @Test
    public void testContains_range_within() {
        CharRange inner = CharRange.isIn('b', 'd');
        CharRange outer = CharRange.isIn('a', 'f');
        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContains_range_outside_negated() {
        CharRange negRange = CharRange.isNotIn('a', 'f');
        CharRange inner = CharRange.isIn('g', 'z');
        assertTrue(negRange.contains(inner));
    }

    @Test
    public void testContains_range_outside_nonNegated() {
        CharRange range = CharRange.isIn('a', 'f');
        CharRange outside = CharRange.isIn('g', 'z');
        assertFalse(range.contains(outside));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContains_nullRange_throws() {
        CharRange range = CharRange.isIn('a', 'f');
        range.contains(null);
    }

    @Test
    public void testEquals_sameObject() {
        CharRange range = CharRange.isIn('a', 'z');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEquals_identicalRange() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('a', 'z');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEquals_differentRange() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'z');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEquals_differentNegation() {
        CharRange range1 = CharRange.is('a');
        CharRange range2 = CharRange.isNot('a');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testHashCode_equalRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertEquals(range1.hashCode(), range2.hashCode());
    }

    @Test
    public void testToString_negatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        String s = range.toString();
        assertTrue(s.startsWith("^"));
        assertFalse(s.contains("-"));
    }

    @Test
    public void testToString_nonNegatedRange() {
        CharRange range = CharRange.is('a', 'f');
        String s = range.toString();
        assertTrue(s.contains("-"));
        assertFalse(s.startsWith("^"));
    }
}

