public ByteVector putLong(final long l) {
    int length = this.length;
    if (length + 8 > data.length) {
        enlarge(8);
    }
    byte[] data = this.data;
    int i = (int) (l >>> 32);
    data[length++] = (byte) (i >>> 24);
    data[length++] = (byte) (i >>> 16);
    data[length++] = (byte) (i >>> 8);
    data[length++] = (byte) i;
    i = (int) l;
    data[length++] = (byte) (i >>> 24);
    data[length++] = (byte) (i >>> 16);
    data[length++] = (byte) (i >>> 8);
    data[length++] = (byte) i;
    this.length = length;
    return this;
}

public ByteVector putLong(final long l) {
    int length = this.length;
    byte[] data = this.data;
    long mask = 0xFFL;
    int shiftCount = 56;
    // Calculate the required capacity for a byte-wise shift
    java.util.stream.LongStream.range(0, 8).forEach(i -> {
        int idx = length + (int) i;
        if (idx >= data.length) {
            enlarge(1);
            data = this.data;
        }
        data[idx] = (byte) ((l >> shiftCount) & mask);
        shiftCount -= 8;
    });
    this.length = length + 8;
    return this;
}

