import static org.junit.Assert.*;

import org.junit.Test;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorCreatesArrayOfSize64() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector bv = new ByteVector(128);
        assertEquals(128, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testPutByteAddsByteCorrectly() {
        ByteVector bv = new ByteVector();
        bv.putByte(0x12);
        assertEquals(1, bv.length);
        assertEquals((byte) 0x12, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesArrayWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0x01);
        bv.putByte(0x02);
        assertEquals(2, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPut11AddsTwoBytes() {
        ByteVector bv = new ByteVector();
        bv.put11(0xAB, 0xCD);
        assertEquals(2, bv.length);
        assertEquals((byte) 0xAB, bv.data[0]);
        assertEquals((byte) 0xCD, bv.data[1]);
    }

    @Test
    public void testPutShortAddsTwoBytes() {
        ByteVector bv = new ByteVector();
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x34, bv.data[1]);
    }

    @Test
    public void testPut12AddsByteAndShort() {
        ByteVector bv = new ByteVector();
        bv.put12(0x11, 0x2222);
        assertEquals(3, bv.length);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x22, bv.data[2]);
    }

    @Test
    public void testPutIntAddsFourBytes() {
        ByteVector bv = new ByteVector();
        bv.putInt(0xAABBCCDD);
        assertEquals(4, bv.length);
        assertEquals((byte) 0xAA, bv.data[0]);
        assertEquals((byte) 0xBB, bv.data[1]);
        assertEquals((byte) 0xCC, bv.data[2]);
        assertEquals((byte) 0xDD, bv.data[3]);
    }

    @Test
    public void testPutLongAddsEightBytes() {
        ByteVector bv = new ByteVector();
        long value = 0x1122334455667788L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x33, bv.data[2]);
        assertEquals((byte) 0x44, bv.data[3]);
        assertEquals((byte) 0x55, bv.data[4]);
        assertEquals((byte) 0x66, bv.data[5]);
        assertEquals((byte) 0x77, bv.data[6]);
        assertEquals((byte) 0x88, bv.data[7]);
    }

    @Test
    public void testPutUTF8EncodesASCIIString() {
        String s = "abc";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(5, bv.length);
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) 0x03, bv.data[1]);
    }

    @Test
    public void testPutUTF8EncodesNonASCIIString() {
        String s = "αβ" ; // Greek characters requiring multi-byte encoding
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
    }

    @Test
    public void testPutByteArrayCopiesContent() {
        byte[] array = {1, 2, 3};
        ByteVector bv = new ByteVector();
        bv.putByteArray(array, 0, 3);
        assertEquals(3, bv.length);
        assertEquals((byte) 1, bv.data[0]);
        assertEquals((byte) 3, bv.data[2]);
    }

    @Test
    public void testEnlargeDoublesArraySize() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(1).putByte(2);
        int originalLength = bv.data.length;
        bv.enlarge(3);
        assertTrue(bv.data.length >= originalLength * 2);
    }

}

