import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIs_singleCharRange() {
        CharRange range = CharRange.is('a');
        assertFalse(range.isNegated());
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
    }

    @Test
    public void testIsNot_singleCharRange() {
        CharRange range = CharRange.isNot('b');
        assertTrue(range.isNegated());
        assertEquals('b', range.getStart());
        assertEquals('b', range.getEnd());
    }

    @Test
    public void testIsIn_range() {
        CharRange range = CharRange.isIn('a', 'z');
        assertFalse(range.isNegated());
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
    }

    @Test
    public void testIsNotIn_range() {
        CharRange range = CharRange.isNotIn('0', '9');
        assertTrue(range.isNegated());
        assertEquals('0', range.getStart());
        assertEquals('9', range.getEnd());
    }

    @Test
    public void testConstructor_ReversesOrder() {
        CharRange range = new CharRange('z', 'a', false);
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testContains_charWithinRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.contains('c'));
    }

    @Test
    public void testContains_charOutsideRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.contains('z'));
    }

    @Test
    public void testContains_charNegated() {
        CharRange range = CharRange.isNot('a', 'z');
        assertFalse(range.contains('b'));
        assertTrue(range.contains('0'));
    }

    @Test
    public void testContains_rangeFullyContained() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('b', 'y');
        assertTrue(range1.contains(range2));
    }

    @Test
    public void testContains_rangeNegated() {
        CharRange range1 = CharRange.isNot('a', 'z');
        CharRange range2 = CharRange.isIn('b', 'y');
        assertFalse(range1.contains(range2));
    }

    @Test
    public void testContains_rangeNegatedWithNegatedRange() {
        CharRange range1 = CharRange.isNot('a', 'z');
        CharRange range2 = CharRange.isNot('a', 'z');
        assertTrue(range1.contains(range2));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContains_nullRange() {
        CharRange range = CharRange.isIn('a', 'z');
        range.contains(null);
    }

    @Test
    public void testEquals_sameObject() {
        CharRange range = CharRange.isIn('a', 'b');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEquals_identicalRange() {
        CharRange range1 = CharRange.isIn('a', 'b');
        CharRange range2 = CharRange.isIn('a', 'b');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEquals_differentRange() {
        CharRange range1 = CharRange.isIn('a', 'b');
        CharRange range2 = CharRange.isIn('a', 'c');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEquals_differentType() {
        CharRange range = CharRange.isIn('a', 'b');
        assertFalse(range.equals("not a range"));
    }

    @Test
    public void testHashCode_consistent() {
        CharRange range1 = CharRange.isIn('a', 'b');
        CharRange range2 = CharRange.isIn('a', 'b');
        assertEquals(range1.hashCode(), range2.hashCode());
    }

    @Test
    public void testToString_inRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertEquals("a-f", range.toString());
    }

    @Test
    public void testToString_negatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        assertEquals("^a-f", range.toString());
    }
}

