import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIs_singleCharRange() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNot_singleCharRange() {
        CharRange range = CharRange.isNot('z');
        assertEquals('z', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testIsIn_range() {
        CharRange range = CharRange.isIn('a', 'f');
        assertEquals('a', range.getStart());
        assertEquals('f', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotIn_range() {
        CharRange range = CharRange.isNotIn('m', 'r');
        assertEquals('m', range.getStart());
        assertEquals('r', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testContains_char_inRange() {
        CharRange range = CharRange.isIn('a', 'z');
        assertTrue(range.contains('m'));
    }

    @Test
    public void testContains_char_outsideRange() {
        CharRange range = CharRange.isIn('a', 'z');
        assertFalse(range.contains('0'));
    }

    @Test
    public void testContains_char_negatedRange() {
        CharRange range = CharRange.isNot('a', 'z');
        assertFalse(range.contains('b'));
        assertTrue(range.contains('0'));
    }

    @Test
    public void testContains_range_contained() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'c');
        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContains_range_notContained_negatedInner() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange innerNegated = CharRange.isNot('a', 'z');
        assertFalse(outer.contains(innerNegated));
    }

    @Test
    public void testContains_range_notContained_outer() {
        CharRange outer = CharRange.isIn('a', 'f');
        CharRange inner = CharRange.isIn('g', 'h');
        assertFalse(outer.contains(inner));
    }

    @Test
    public void testEquals_sameObject() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEquals_equalRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEquals_differentRanges() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'e');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEquals_differentNegation() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isNotIn('a', 'f');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testHashCode_consistency() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertEquals(range1.hashCode(), range2.hashCode());
    }

    @Test
    public void testToString_inRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertEquals("a-f", range.toString());
    }

    @Test
    public void testToString_negatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        assertEquals("^a-f", range.toString());
    }

    @Test
    public void testConstructor_orderReversal() {
        CharRange range = CharRange.isIn('z', 'a');
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContains_nullRangeThrows() {
        CharRange range = CharRange.isIn('a', 'f');
        range.contains(null);
    }
}

