/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import static org.junit.Assert.*;

import org.junit.Test;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorCreatesArrayOfSize64() {
        ByteVector bv = new ByteVector();
        assertNotNull(bv.data);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testConstructorWithSizeCreatesArrayOfCorrectSize() {
        ByteVector bv = new ByteVector(128);
        assertNotNull(bv.data);
        assertEquals(128, bv.data.length);
    }

    @Test
    public void testPutByteIncreasesLengthAndStoresValue() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargeArrayIfNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(20);
        assertTrue(bv.data.length >= 2);
        assertEquals(1, bv.length);
        assertEquals(20, bv.data[0]);
    }

    @Test
    public void testPut11StoresTwoBytesAndIncreasesLength() {
        ByteVector bv = new ByteVector(2);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPut11EnlargesArrayIfNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.put11(3, 4);
        assertTrue(bv.data.length >= 4);
        assertEquals(2, bv.length);
        assertEquals(3, bv.data[0]);
        assertEquals(4, bv.data[1]);
    }

    @Test
    public void testPutShortStoresCorrectBytes() {
        ByteVector bv = new ByteVector();
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x34, bv.data[1]);
    }

    @Test
    public void testPut12StoresCorrectBytes() {
        ByteVector bv = new ByteVector();
        bv.put12(0xAA, 0xBB);
        assertEquals(3, bv.length);
        assertEquals((byte) 0xAA, bv.data[0]);
        assertEquals((byte) 0xBB, bv.data[2]);
    }

    @Test
    public void testPutIntStoresCorrectBytes() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x33, bv.data[2]);
        assertEquals((byte) 0x44, bv.data[3]);
    }

    @Test
    public void testPutLongStoresCorrectBytes() {
        ByteVector bv = new ByteVector();
        long value = 0x0102030405060708L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertEquals((byte) 0x03, bv.data[2]);
        assertEquals((byte) 0x04, bv.data[3]);
        assertEquals((byte) 0x05, bv.data[4]);
        assertEquals((byte) 0x06, bv.data[5]);
        assertEquals((byte) 0x07, bv.data[6]);
        assertEquals((byte) 0x08, bv.data[7]);
    }

    @Test
    public void testPutUTF8StoresStringInBytes() {
        String s = "abc";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length >= 5);
        assertEquals(0, bv.data[0]);
        assertEquals(3, bv.data[1]);
        assertEquals((byte) 'a', bv.data[2]);
        assertEquals((byte) 'b', bv.data[3]);
        assertEquals((byte) 'c', bv.data[4]);
    }

    @Test
    public void testPutUTF8WithNonAsciiCharactersEnlargesBuffer() {
        String s = "あい"; // characters outside 1-127 range
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length > 2);
    }

    @Test
    public void testPutByteArrayCopiesArray() {
        byte[] b = {1, 2, 3, 4};
        ByteVector bv = new ByteVector();
        bv.putByteArray(b, 1, 2);
        assertEquals(2, bv.length);
        assertEquals(2, bv.data[0]);
        assertEquals(3, bv.data[1]);
    }

    @Test
    public void testEnlargeDoublesArraySize() {
        ByteVector bv = new ByteVector(4);
        int oldLength = bv.data.length;
        bv.enlarge(10);
        assertTrue(bv.data.length >= oldLength * 2);
    }
}

/**
 * <p>A contiguous range of characters, optionally negated.</p>
 * 
 * <p>Instances are immutable.</p>
 */
public class CharRange {

    /** The first character, inclusive, in the range. */
    private final char start;
    /** The last character, inclusive, in the range. */
    private final char end;
    /** True if the range is everything except the characters specified. */
    private final boolean negated;

    /** Cached toString. */
    private transient String iToString;

    /**
     * <p>Constructs a {@code CharRange} over a set of characters,
     * optionally negating the range.</p>
     *
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     * 
     * <p>If start and end are in the wrong order, they are reversed.
     * Thus {@code a-e} is the same as {@code e-a}.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @param negated  true to express everything except the range
     */
    private CharRange(char start, char end, final boolean negated) {
        super();
        if (start > end) {
            final char temp = start;
            start = end;
            end = temp;
        }

        this.start = start;
        this.end = end;
        this.negated = negated;
    }

    /**
     * <p>Constructs a {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange is(final char ch) {
        return new CharRange(ch, ch, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNot(final char ch) {
        return new CharRange(ch, ch, true);
    }

    /**
     * <p>Constructs a {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isIn(final char start, final char end) {
        return new CharRange(start, end, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterRange() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotSingleCharacterRange() {
        CharRange range = CharRange.isNot('z');
        assertEquals('z', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testIsInRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertEquals('a', range.getStart());
        assertEquals('f', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotInRange() {
        CharRange range = CharRange.isNotIn('m', 'q');
        assertEquals('m', range.getStart());
        assertEquals('q', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testContainsCharacterWithinRange() {
        CharRange range = CharRange.isIn('a', 'z');
        assertTrue(range.contains('a'));
        assertTrue(range.contains('m'));
        assertTrue(range.contains('z'));
    }

    @Test
    public void testContainsCharacterOutsideRange() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.contains('z'));
        assertFalse(range.contains('h'));
    }

    @Test
    public void testContainsCharacterInNegatedRange() {
        CharRange range = CharRange.isNot('a', 'f');
        assertFalse(range.contains('b'));
        assertTrue(range.contains('z'));
    }

    @Test
    public void testContainsRangeWithinRange() {
        CharRange range1 = CharRange.isIn('a', 'z');
        CharRange range2 = CharRange.isIn('b', 'y');
        assertTrue(range1.contains(range2));
    }

    @Test
    public void testContainsRangeOutsideRange() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('g', 'z');
        assertFalse(range1.contains(range2));
    }

    @Test
    public void testContainsNegatedRangeWhenBothNegated() {
        CharRange range1 = CharRange.isNot('a', 'z');
        CharRange range2 = CharRange.isNot('a', 'z');
        assertTrue(range1.contains(range2));
    }

    @Test
    public void testContainsNegatedRangeWhenRangeWithinNegation() {
        CharRange range1 = CharRange.isNot('a', 'z');
        CharRange range2 = CharRange.isNot('a', 'y');
        assertFalse(range1.contains(range2));
    }

    @Test
    public void testEqualsSameObject() {
        CharRange range = CharRange.isIn('a', 'f');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEqualsDifferentObject() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'f');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEqualsDifferentRange() {
        CharRange range1 = CharRange.isIn('a', 'f');
        CharRange range2 = CharRange.isIn('a', 'g');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEqualsNull() {
        CharRange range = CharRange.isIn('a', 'f');
        assertFalse(range.equals(null));
    }

    @Test
    public void testHashCodeConsistency() {
        CharRange range = CharRange.isIn('a', 'f');
        assertEquals(range.hashCode(), range.hashCode());
    }

    @Test
    public void testToStringNotNegatedSingleChar() {
        CharRange range = CharRange.is('x');
        String str = range.toString();
        assertEquals("x", str);
    }

    @Test
    public void testToStringNegatedSingleChar() {
        CharRange range = CharRange.isNot('x');
        String str = range.toString();
        assertEquals("^x", str);
    }

    @Test
    public void testToStringRange() {
        CharRange range = CharRange.isIn('a', 'z');
        String str = range.toString();
        assertEquals("a-z", str);
    }

    @Test
    public void testToStringNegatedRange() {
        CharRange range = CharRange.isNotIn('a', 'z');
        String str = range.toString();
        assertEquals("^a-z", str);
    }
}

/**
 * <p>A contiguous range of characters, optionally negated.</p>
 * 
 * <p>Instances are immutable.</p>
 */
public class CharRange {

    /** The first character, inclusive, in the range. */
    private final char start;
    /** The last character, inclusive, in the range. */
    private final char end;
    /** True if the range is everything except the characters specified. */
    private final boolean negated;

    /** Cached toString. */
    private transient String iToString;

    /**
     * <p>Constructs a {@code CharRange} over a set of characters,
     * optionally negating the range.</p>
     *
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     * 
     * <p>If start and end are in the wrong order, they are reversed.
     * Thus {@code a-e} is the same as {@code e-a}.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @param negated  true to express everything except the range
     */
    private CharRange(char start, char end, final boolean negated) {
        super();
        if (start > end) {
            final char temp = start;
            start = end;
            end = temp;
        }

        this.start = start;
        this.end = end;
        this.negated = negated;
    }

    /**
     * <p>Constructs a {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange is(final char ch) {
        return new CharRange(ch, ch, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNot(final char ch) {
        return new CharRange(ch, ch, true);
    }

    /**
     * <p>Constructs a {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isIn(final char start, final char end) {
        return new CharRange(start, end, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterRange() {
        CharRange cr = CharRange.is('a');
        assertEquals('a', cr.getStart());
        assertEquals('a', cr.getEnd());
        assertFalse(cr.isNegated());
    }

    @Test
    public void testIsNotSingleCharacterRange() {
        CharRange cr = CharRange.isNot('z');
        assertEquals('z', cr.getStart());
        assertEquals('z', cr.getEnd());
        assertTrue(cr.isNegated());
    }

    @Test
    public void testIsInRange() {
        CharRange cr = CharRange.isIn('a', 'f');
        assertEquals('a', cr.getStart());
        assertEquals('f', cr.getEnd());
        assertFalse(cr.isNegated());
    }

    @Test
    public void testIsNotInRange() {
        CharRange cr = CharRange.isNotIn('x', 'z');
        assertEquals('x', cr.getStart());
        assertEquals('z', cr.getEnd());
        assertTrue(cr.isNegated());
    }

    @Test
    public void testContainsCharacterWithinRange() {
        CharRange cr = CharRange.isIn('a', 'z');
        assertTrue(cr.contains('c'));
    }

    @Test
    public void testContainsCharacterOutsideRange() {
        CharRange cr = CharRange.isIn('a', 'z');
        assertFalse(cr.contains('0'));
    }

    @Test
    public void testContainsInNegatedRange() {
        CharRange cr = CharRange.isNotIn('a', 'z');
        assertFalse(cr.contains('b'));
        assertTrue(cr.contains('0'));
    }

    @Test
    public void testContainsRangeWithinRange() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'y');

        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContainsRangePartiallyOutside() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange outside = CharRange.isIn('y', 'z');

        assertTrue(outer.contains(outside));
    }

    @Test
    public void testContainsRangeNotContained() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange outside = CharRange.isIn('z', 'z');
        CharRange notContained = CharRange.isIn('z', 'z');
        CharRange negatedOuter = CharRange.isNotIn('a', 'z');

        assertFalse(outer.contains(notContained));
        assertFalse(negatedOuter.contains(outer));
    }

    @Test
    public void testEqualsSameObject() {
        CharRange cr = CharRange.is('a');
        assertTrue(cr.equals(cr));
    }

    @Test
    public void testEqualsDifferentObjectSameAttributes() {
        CharRange cr1 = CharRange.is('a');
        CharRange cr2 = CharRange.is('a');
        assertTrue(cr1.equals(cr2));
    }

    @Test
    public void testEqualsDifferentObjectDifferentAttributes() {
        CharRange cr1 = CharRange.is('a');
        CharRange cr2 = CharRange.is('b');
        assertFalse(cr1.equals(cr2));
    }

    @Test
    public void testEqualsNullObject() {
        CharRange cr = CharRange.is('a');
        assertFalse(cr.equals(null));
    }

    @Test
    public void testHashCodeEqualForEqualObjects() {
        CharRange cr1 = CharRange.is('a');
        CharRange cr2 = CharRange.is('a');
        assertEquals(cr1.hashCode(), cr2.hashCode());
    }

    @Test
    public void testToStringNonNegatedSingleChar() {
        CharRange cr = CharRange.is('x');
        assertEquals("x", cr.toString());
    }

    @Test
    public void testToStringNegatedSingleChar() {
        CharRange cr = CharRange.isNot('x');
        assertEquals("^x", cr.toString());
    }

    @Test
    public void testToStringRange() {
        CharRange cr = CharRange.isIn('a', 'f');
        assertEquals("a-f", cr.toString());
    }

    @Test
    public void testToStringNegatedRange() {
        CharRange cr = CharRange.isNotIn('a', 'f');
        assertEquals("^a-f", cr.toString());
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByteEnlargesAndAdd() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);

        // Trigger enlarge
        bv.putByte(20);
        assertEquals(2, bv.length);
        assertEquals(10, bv.data[0]);
        assertEquals(20, bv.data[1]);
    }

    @Test
    public void testPut11AndPut12() {
        ByteVector bv = new ByteVector(2);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);

        bv.put12(3, 4);
        assertEquals(5, bv.length);
        assertEquals(3, bv.data[2]);
        assertEquals(4, bv.data[3]);
    }

    @Test
    public void testPutShortEnlargesAndAdds() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(258);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPutIntEnlargesAndAdds() {
        ByteVector bv = new ByteVector(1);
        bv.putInt(16909060); // 0x01020304
        assertEquals(4, bv.length);
        assertEquals(1, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
        assertEquals(3, bv.data[2] & 0xFF);
        assertEquals(4, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutLongEnlargesAndAdds() {
        ByteVector bv = new ByteVector(1);
        long value = 0x0102030405060708L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
        assertEquals(0x03, bv.data[2] & 0xFF);
        assertEquals(0x04, bv.data[3] & 0xFF);
        assertEquals(0x05, bv.data[4] & 0xFF);
        assertEquals(0x06, bv.data[5] & 0xFF);
        assertEquals(0x07, bv.data[6] & 0xFF);
        assertEquals(0x08, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutUTF8ASCII() {
        String s = "abc";
        ByteVector bv = new ByteVector(3);
        bv.putUTF8(s);
        assertEquals(2 + s.length(), bv.length);
        assertEquals(0, bv.data[0]);
        assertEquals(3, bv.data[1]);
        assertEquals('a', bv.data[2]);
        assertEquals('b', bv.data[3]);
        assertEquals('c', bv.data[4]);
    }

    @Test
    public void testPutUTF8NonASCII() {
        String s = "ñ";
        ByteVector bv = new ByteVector(2);
        bv.putUTF8(s);
        // The length should be 2 + bytes needed for ñ
        assertTrue(bv.length >= 3);
        assertEquals(0, bv.data[0]);
        assertEquals(1, bv.data[1]);
        // First byte after length should be the first character's encoded byte
        assertTrue(bv.data[2] != 0);
    }

    @Test
    public void testPutByteArrayNullAndEmpty() {
        ByteVector bv = new ByteVector(2);
        bv.putByteArray(null, 0, 0);
        assertEquals(0, bv.length);
        byte[] array = {1, 2, 3};
        bv.putByteArray(array, 0, 3);
        assertEquals(3, bv.length);
        assertEquals(1, bv.data[0] & 0xFF);
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import static org.junit.Assert.*;

import org.junit.Test;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialSize() {
        ByteVector bv = new ByteVector();
        assertEquals(0, bv.length);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testParameterizedConstructorInitialSize() {
        ByteVector bv = new ByteVector(128);
        assertEquals(0, bv.length);
        assertEquals(128, bv.data.length);
    }

    @Test
    public void testPutByteIncreasesLengthAndStoresValue() {
        ByteVector bv = new ByteVector();
        byte result = bv.putByte(10).data[0];
        assertEquals(1, bv.length);
        assertEquals(10, result);
    }

    @Test
    public void testPut11StoresTwoBytesAndIncreasesLength() {
        ByteVector bv = new ByteVector();
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPutShortStoresTwoBytesCorrectly() {
        ByteVector bv = new ByteVector();
        bv.putShort(0xABCD);
        assertEquals(2, bv.length);
        assertEquals((byte) 0xAB, bv.data[0]);
        assertEquals((byte) 0xCD, bv.data[1]);
    }

    @Test
    public void testPut12StoresByteAndShortCorrectly() {
        ByteVector bv = new ByteVector();
        bv.put12(0x12, 0x345);
        assertEquals(3, bv.length);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x03, bv.data[1]);
        assertEquals((byte) 0x45, bv.data[2]);
    }

    @Test
    public void testPutIntStoresFourBytesCorrectly() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
        assertEquals((byte) 0x33, bv.data[2]);
        assertEquals((byte) 0x44, bv.data[3]);
    }

    @Test
    public void testPutLongStoresEightBytesCorrectly() {
        ByteVector bv = new ByteVector();
        long val = 0x0102030405060708L;
        bv.putLong(val);
        assertEquals(8, bv.length);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
        assertEquals((byte) 0x03, bv.data[2]);
        assertEquals((byte) 0x04, bv.data[3]);
        assertEquals((byte) 0x05, bv.data[4]);
        assertEquals((byte) 0x06, bv.data[5]);
        assertEquals((byte) 0x07, bv.data[6]);
        assertEquals((byte) 0x08, bv.data[7]);
    }

    @Test
    public void testPutUTF8StringStoresCorrectBytes() {
        String s = "abcX";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(2 + s.length(), bv.data.length >= bv.length ? bv.length : 0);
        assertEquals((byte) s.length(), bv.data[2]);
    }

    @Test
    public void testPutUTF8StringWithSpecialCharsStoresCorrectBytes() {
        String s = "Юлиана";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length >= s.length() + 2);
        assertEquals((byte) (s.length()), bv.data[1]);
    }

    @Test
    public void testPutByteArrayCopiesData() {
        byte[] arr = {1, 2, 3, 4};
        ByteVector bv = new ByteVector();
        bv.putByteArray(arr, 0, arr.length);
        assertEquals(arr.length, bv.length);
        assertArrayEquals(arr, java.util.Arrays.copyOfRange(bv.data, 0, bv.length));
    }

    @Test
    public void testEnlargeDoublesSizeWhenNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(1);
        bv.putByte(2);
        int initialCapacity = bv.data.length;
        bv.putByte(3); 
        assertTrue(bv.data.length >= initialCapacity);
        assertEquals(3, bv.length);
        assertEquals((byte)1, bv.data[0]);
        assertEquals((byte)2, bv.data[1]);
        assertEquals((byte)3, bv.data[2]);
    }
}

