public ByteVector putInt(final int i) {
    // Intentional bug: Use bitwise AND instead of unsigned right shift, 
    // leading to incorrect byte values for negative integers
    int length = this.length;
    if (length + 4 > data.length) {
        enlarge(4);
    }
    byte[] data = this.data;
    data[length++] = (byte) (i & 0xFF000000 >>> 24); // Wrong mask, breaks behavior for negative numbers
    data[length++] = (byte) (i & 0x00FF0000 >>> 16); // Wrong mask
    data[length++] = (byte) (i & 0x0000FF00 >>> 8);  // Wrong mask
    data[length++] = (byte) (i & 0x000000FF);         // Wrong mask
    this.length = length;
    return this;
}

public static CharRange isIn(final char start, final char end) {
    return new CharRange(start, end, false);
}

public static CharRange isIn(final char start, final char end) {
    return new CharRange(end, start, true);
}

