import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() {
        ByteVector v = new ByteVector();
        assertEquals(64, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector v = new ByteVector(3);
        assertEquals(3, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void testPutByteWritesAndIncrementsLength() {
        ByteVector v = new ByteVector(1);
        v.putByte(0xAB);
        assertEquals(1, v.length);
        assertEquals((byte) 0xAB, v.data[0]);
    }

    @Test
    public void testPutByteEnlargesWhenFull() {
        ByteVector v = new ByteVector(1);
        v.putByte(1).putByte(2);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void testPutShortBigEndian() {
        ByteVector v = new ByteVector(2);
        v.putShort(0x1234);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPutIntBigEndian() {
        ByteVector v = new ByteVector(4);
        v.putInt(0x01020304);
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 1, 2, 3, 4 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutLongBigEndian() {
        ByteVector v = new ByteVector(8);
        v.putLong(0x0102030405060708L);
        assertEquals(8, v.length);
        assertArrayEquals(
                new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4], v.data[5], v.data[6], v.data[7] }
        );
    }

    @Test
    public void testPutUTF8AsciiWritesLengthPrefixAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("Hi");
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0, 2, 'H', 'i' }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutUTF8TwoByteCharEncodingAndLengthPrefix() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u00A2"); // '¢' => C2 A2
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0, 2, (byte) 0xC2, (byte) 0xA2 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutUTF8ThreeByteCharEncodingAndLengthPrefix() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u20AC"); // '€' => E2 82 AC
        assertEquals(5, v.length);
        assertArrayEquals(
                new byte[] { 0, 3, (byte) 0xE2, (byte) 0x82, (byte) 0xAC },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] }
        );
    }

    @Test
    public void testPutUTF8MixedTriggersRecomputeAndCorrectPrefix() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("A\u20AC"); // 'A' + '€' => bytes: 41 E2 82 AC, length prefix 0x0004
        assertEquals(6, v.length);
        assertArrayEquals(
                new byte[] { 0, 4, 'A', (byte) 0xE2, (byte) 0x82, (byte) 0xAC },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4], v.data[5] }
        );
    }

    @Test
    public void testPutUTF8EnlargesWhenOptimisticCapacityInsufficientButRecomputedBigger() {
        ByteVector v = new ByteVector(5); // enough for optimistic 2+2=4, not enough for actual 2+4=6
        v.putUTF8("A\u20AC");
        assertTrue(v.data.length >= 6);
        assertEquals(6, v.length);
    }

    @Test
    public void testPutByteArrayCopiesBytes() {
        ByteVector v = new ByteVector(3);
        v.putByteArray(new byte[] { 9, 8, 7 }, 1, 2);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 8, 7 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPutByteArrayWithNullWritesZerosAndAdvancesLength() {
        ByteVector v = new ByteVector(2);
        v.putByteArray(null, 0, 2);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0, 0 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPutByteArrayEnlargesAndPreservesExistingData() {
        ByteVector v = new ByteVector(2);
        v.putByte(1).putByte(2);
        v.putByteArray(new byte[] { 3, 4, 5 }, 0, 3);
        assertEquals(5, v.length);
        assertArrayEquals(new byte[] { 1, 2, 3, 4, 5 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
    }

    @Test
    public void testPackagePrivatePut11WritesTwoBytes() {
        ByteVector v = new ByteVector(2);
        v.put11(0xFE, 0xDC);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { (byte) 0xFE, (byte) 0xDC }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPackagePrivatePut12WritesByteThenShortBigEndian() {
        ByteVector v = new ByteVector(3);
        v.put12(0x7F, 0x1234);
        assertEquals(3, v.length);
        assertArrayEquals(new byte[] { 0x7F, 0x12, 0x34 }, new byte[] { v.data[0], v.data[1], v.data[2] });
    }

    @Test
    public void testChainingReturnsSameInstance() {
