import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void utf8LengthRecalculationAndEnlargeKeepsAllBytes() {
        ByteVector v = new ByteVector(4);
        v.putByte(0x55);
        v.putUTF8("A\u0080\u0800"); // forces non-ASCII path: 1 + 2 + 3 bytes = 6

        byte[] expected = new byte[] {
            0x55,
            0x00, 0x06,
            0x41,
            (byte) 0xC2, (byte) 0x80,
            (byte) 0xE0, (byte) 0xA0, (byte) 0x80
        };

        assertEquals(expected.length, v.length);
        assertArrayEquals(expected, java.util.Arrays.copyOf(v.data, v.length));
    }
}

