import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutUTF8WithTwoByteCharAndEnlargeUpdatesLengthHeaderAndContent() throws Exception {
        ByteVector v = new ByteVector(3); // force enlarge when writing UTF8 with 2-byte char
        v.putByte(0x55); // prefix to ensure header rewrite uses v.length index correctly
        v.putUTF8("\u0080"); // U+0080 -> 2 bytes in modified UTF-8 encoding here

        assertEquals(1 + 2 + 2, v.length);

        byte[] actual = new byte[v.length];
        System.arraycopy(v.data, 0, actual, 0, v.length);
        assertArrayEquals(new byte[] { 0x55, 0x00, 0x02, (byte) 0xC2, (byte) 0x80 }, actual);
    }
}

