import org.junit.Test;

import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialState() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testConstructorWithInitialSizeInitialState() {
        ByteVector bv = new ByteVector(3);
        assertEquals(3, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testPutByteWritesAndIncrementsLength() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0xFE);
        assertEquals(1, bv.length);
        assertEquals((byte) 0xFE, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPut11WritesTwoBytes() {
        ByteVector bv = new ByteVector(2);
        bv.put11(0x12, 0xFE);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0x12, (byte) 0xFE }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPut11EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPutShortBigEndian() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPutShortEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPut12WritesByteThenShort() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0x7F, 0x0102);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0x7F, 0x01, 0x02 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void testPut12EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.put12(1, 2);
        assertEquals(3, bv.length);
        assertTrue(bv.data.length >= 3);
    }

    @Test
    public void testPutIntBigEndian() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 },
                new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void testPutIntEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertTrue(bv.data.length >= 4);
    }

    @Test
    public void testPutLongBigEndian() {
        ByteVector bv = new ByteVector(8);
        bv.putLong(0x0102030405060708L);
        assertEquals(8, bv.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 },
                new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4], bv.data[5], bv.data[6], bv.data[7] });
    }

    @Test
    public void testPutLongEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(7);
        bv.putLong(1L);
        assertEquals(8, bv.length);
        assertTrue(bv.data.length >= 8);
    }

    @Test
    public void testPutUTF8AsciiEncodesLengthAndBytes() {
        ByteVector bv = new ByteVector(5);
        bv.putUTF8("AB");
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, 0x41, 0x42 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void testPutUTF8TwoByteCharUpdatesLengthFieldToByteLength() {
        ByteVector bv = new ByteVector(4);
        bv.putUTF8("\u0080");
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC2, (byte) 0x80 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void testPutUTF8ThreeByteCharUpdatesLengthFieldToByteLength() {
        ByteVector bv = new ByteVector(5);
        bv.putUTF8("\u0800");
        assertEquals(5, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x03, (byte) 0xE0, (byte) 0xA0, (byte) 0x80 },
                new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4] });
    }

    @Test
    public void testPutUTF8EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(3);
        bv.putUTF8("\u0800");
        assertEquals(5, bv.length);
        assertTrue(bv.data.length >= 5);
    }

    @Test
    public void testPutByteArrayCopiesBytes() {
        ByteVector bv = new ByteVector(4);
        byte[] src = new byte[] { 9, 8, 7, 6, 5 };
        bv.putByteArray(src, 1, 3);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 8, 7, 6 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void testPutByteArrayNullWritesZeroBytes() {
        ByteVector bv = new ByteVector(2);
        bv.putByteArray(null, 0, 2);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0, 0 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPutByteArrayEnlargesAndPreservesExistingBytes() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0x11);
        bv.putByteArray(new byte[] { 0x22, 0x33 }, 0, 2);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0x11, 0x22, 0x33 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void testChainingReturnsSameInstance() {
        ByteVector bv = new ByteVector(1);
        ByteVector returned = bv.putByte(1).putShort(2);
        assertSame(bv, returned);
        assertEquals(3, bv.length);
    }
}

