import static org.junit.Assert.*;
import org.junit.Test;

public class ByteVectorTest {

    @Test
    public void testPutByte_singleByte() {
        ByteVector bv = new ByteVector();
        bv.putByte(0x12);
        assertEquals(1, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
    }

    @Test
    public void testPutByte_enlarge() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0xAB);
        bv.putByte(0xCD);
        assertEquals(2, bv.length);
        assertEquals(0xAB, bv.data[0] & 0xFF);
        assertEquals(0xCD, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut11_twoBytes() {
        ByteVector bv = new ByteVector();
        bv.put11(0x01, 0x02);
        assertEquals(2, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShort_positive() {
        ByteVector bv = new ByteVector();
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
        assertEquals(0x34, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut12_mixed() {
        ByteVector bv = new ByteVector();
        bv.put12(0x0A, 0x1234);
        assertEquals(3, bv.length);
        assertEquals(0x0A, bv.data[0] & 0xFF);
        assertEquals(0x12, bv.data[1] & 0xFF);
        assertEquals(0x34, bv.data[2] & 0xFF);
    }

    @Test
    public void testPutInt_positive() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals(0x11, bv.data[0] & 0xFF);
        assertEquals(0x22, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutLong_positive() {
        ByteVector bv = new ByteVector();
        long l = 0x0102030405060708L;
        bv.putLong(l);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutUTF8_ascii() {
        ByteVector bv = new ByteVector();
        String str = "Hello";
        bv.putUTF8(str);
        assertTrue(bv.length >= 2 + str.length());
        assertEquals((byte) (str.length()), bv.data[1] & 0xFF);
        assertEquals((byte) 'H', bv.data[2] & 0xFF);
    }

    @Test
    public void testPutUTF8_nonAscii() {
        ByteVector bv = new ByteVector();
        String str = "ñ"; // character > '\177'
        bv.putUTF8(str);
        assertTrue(bv.length >= 2 + str.length());
        // bytes should contain UTF-8 encoding of 'ñ' (which is 0xC3 0xB1)
        boolean hasUtf8Bytes = false;
        for (byte b : bv.data) {
            if ((b & 0xFF) == 0xC3 || (b & 0xFF) == 0xB1) {
                hasUtf8Bytes = true;
                break;
            }
        }
        assertTrue(hasUtf8Bytes);
    }

    @Test
    public void testPutByteArray_copy() {
        ByteVector bv = new ByteVector();
        byte[] b = {0x10, 0x20, 0x30};
        bv.putByteArray(b, 0, 3);
        assertEquals(3, bv.length);
        assertEquals(0x10, bv.data[0] & 0xFF);
        assertEquals(0x20, bv.data[1] & 0xFF);
    }

    @Test
    public void testEnlarge_tripleSize() {
        ByteVector bv = new ByteVector(1);
        int initialCapacity = bv.data.length;
