        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorCreatesArrayWithSize64() {
        ByteVector bv = new ByteVector();
        assertEquals(0, bv.length);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testInitialSizeConstructorCreatesArrayWithGivenSize() {
        ByteVector bv = new ByteVector(128);
        assertEquals(0, bv.length);
        assertEquals(128, bv.data.length);
    }

    @Test
    public void testPutByteIncrementsLengthAndStoresData() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesArrayWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1);
        bv.putByte(2);
        assertTrue(bv.data.length >= 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
    }

    @Test
    public void testPut11StoresTwoBytesCorrectly() {
        ByteVector bv = new ByteVector();
        bv.put11(5, 15);
        assertEquals(2, bv.length);
        assertEquals(5, bv.data[0]);
        assertEquals(15, bv.data[1]);
    }

    @Test
    public void testPutShortStoresTwoBytesInOrder() {
        ByteVector bv = new ByteVector();
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
        assertEquals(0x34, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut12StoresBytesCorrectly() {
        ByteVector bv = new ByteVector();
        bv.put12(0xAB, 0xCDEF);
        assertEquals(3, bv.length);
        assertEquals(0xAB, bv.data[0] & 0xFF);
        assertEquals(0xCDEF >>> 8, bv.data[1] & 0xFF);
        assertEquals(0xCDEF & 0xFF, bv.data[2] & 0xFF);
    }

    @Test
    public void testPutIntStoresFourBytes() {
        ByteVector bv = new ByteVector();
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals(0x11, bv.data[0] & 0xFF);
        assertEquals(0x22, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutLongStoresEightBytes() {
        ByteVector bv = new ByteVector();
        bv.putLong(0x0102030405060708L);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
        assertEquals(0x03, bv.data[2] & 0xFF);
        assertEquals(0x04, bv.data[3] & 0xFF);
        assertEquals(0x05, bv.data[4] & 0xFF);
        assertEquals(0x06, bv.data[5] & 0xFF);
        assertEquals(0x07, bv.data[6] & 0xFF);
        assertEquals(0x08, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutUTF8StoresStringWithOneByteChars() {
        String s = "abc";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertEquals(5, bv.length);
        assertEquals(0, bv.data[0]);
        assertEquals(3, bv.data[1]);
        assertEquals('a', bv.data[2]);
        assertEquals('b', bv.data[3]);
        assertEquals('c', bv.data[4]);
    }

    @Test
    public void testPutUTF8StoresStringWithMultiByteChars() {
        String s = "éä"; // characters requiring multi-byte encoding
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length >= 5);
        assertEquals((byte) (s.length() >>> 8), bv.data[0]);
        assertEquals((byte) s.length(), bv.data[1]);
    }

    @Test
    public void testPutByteArrayCopiesData() {
        byte[] input = {1, 2, 3};
        ByteVector bv = new ByteVector();
        bv.putByteArray(input, 0, input.length);
        assertEquals(3, bv.length);
        assertEquals(1, bv.data[0]);
        assertEquals(2, bv.data[1]);
        assertEquals(3, bv.data[2]);
    }

    @Test
    public void testEnlargeDoublesArraySize() {
        ByteVector bv = new ByteVector(1);
        int initialSize = bv.data.length;
        bv.putByte(1);
        bv.putByte(2); // should trigger enlarge
        assertTrue(bv.data.length >= initialSize * 2);
    }
}

public ByteVector putInt(final int i) {
