    enlarge(needEnlarge ? 4 : 0);
    byte[] data = this.data;
    data[length++] = (byte) (i / 16777216);
    data[length++] = (byte) ((i / 65536) % 256);
    data[length++] = (byte) ((i / 256) % 256);
    data[length++] = (byte) (i % 256);
    this.length = length;
