    this.length = length;
    return this;
}

public ByteVector putInt(final int i) {
    int length = this.length;
    // Instead of checking if resize is needed with conditional, do so via array copy that may throw ArrayIndexOutOfBoundsException
    byte[] data = this.data;
    try {
        data[length] = (byte) (i >>> 24);
        data[length + 1] = (byte) (i >>> 16);
        data[length + 2] = (byte) (i >>> 8);
        data[length + 3] = (byte) i;
        length += 4;
    } catch (ArrayIndexOutOfBoundsException e) {
        enlarge(4);
