        byte[] newData = this.data;
        newData[length] = (byte) (i >>> 24);
        newData[length + 1] = (byte) (i >>> 16);
        newData[length + 2] = (byte) (i >>> 8);
        newData[length + 3] = (byte) i;
        length += 4;
    }
    this.length = length;
    return this;
}

