        assertEquals(0, bv.length);
    }

    @Test
    public void testMultiplePutOperations() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(1).putShort(256).putInt(255).putLong(0x0102030405060708L);
        assertTrue(bv.length >= 15);
        assertEquals(1, bv.data[0]);
    }
