    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByteWithinInitialCapacity() {
        ByteVector bv = new ByteVector(10);
        bv.putByte(5);
        assertEquals(1, bv.length);
        assertEquals(5, bv.data[0] & 0xFF);
    }

    @Test
    public void testPutByteEnlargesArray() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(10);
        bv.putByte(20);
        assertEquals(2, bv.length);
        assertEquals(10, bv.data[0] & 0xFF);
        assertEquals(20, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut11WithinCapacity() {
        ByteVector bv = new ByteVector(2);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertEquals(1, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut11EnlargesArray() {
        ByteVector bv = new ByteVector(1);
        bv.put11(3, 4);
        assertEquals(2, bv.length);
        assertEquals(3, bv.data[0] & 0xFF);
        assertEquals(4, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShortWithinCapacity() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
        assertEquals(0x34, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShortEnlargesArray() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0xABCD);
        assertEquals(2, bv.length);
        assertEquals(0xAB, bv.data[0] & 0xFF);
        assertEquals(0xCD, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut12WithinCapacity() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0x55, 0x666);
        assertEquals(3, bv.length);
        assertEquals(0x55, bv.data[0] & 0xFF);
        assertEquals(0x06, bv.data[1] & 0xFF);
        assertEquals(0x66, bv.data[2] & 0xFF);
    }

    @Test
    public void testPut12EnlargesArray() {
        ByteVector bv = new ByteVector(2);
        bv.put12(0xAA, 0xBBBB);
        assertEquals(3, bv.length);
        assertEquals(0xAA, bv.data[0] & 0xFF);
        assertEquals(0x0B, bv.data[1] & 0xFF);
        assertEquals(0xBB, bv.data[2] & 0xFF);
    }

    @Test
    public void testPutIntWithinCapacity() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x11223344);
        assertEquals(4, bv.length);
        assertEquals(0x11, bv.data[0] & 0xFF);
        assertEquals(0x22, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutIntEnlargesArray() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0xAABBCCDD);
        assertEquals(4, bv.length);
        assertEquals(0xAA, bv.data[0] & 0xFF);
        assertEquals(0xBB, bv.data[1] & 0xFF);
        assertEquals(0xCC, bv.data[2] & 0xFF);
        assertEquals(0xDD, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutLongWithinCapacity() {
        ByteVector bv = new ByteVector(8);
        long value = 0x0102030405060708L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutLongEnlargesArray() {
        ByteVector bv = new ByteVector(7);
        long value = 0x0A0B0C0D0E0F1011L;
        bv.putLong(value);
        assertEquals(8, bv.length);
        assertEquals(0x0A, bv.data[0] & 0xFF);
        assertEquals(0x0B, bv.data[1] & 0xFF);
        assertEquals(0x0C, bv.data[2] & 0xFF);
        assertEquals(0x0D, bv.data[3] & 0xFF);
        assertEquals(0x0E, bv.data[4] & 0xFF);
        assertEquals(0x0F, bv.data[5] & 0xFF);
        assertEquals(0x10, bv.data[6] & 0xFF);
        assertEquals(0x11, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutUTF8Ascii() {
        String s = "hello";
        ByteVector bv = new ByteVector(10);
        bv.putUTF8(s);
        assertEquals(7, bv.length);
        assertEquals(0, bv.data[0] & 0xFF);
        assertEquals(5, bv.data[1] & 0xFF);
        assertEquals('h', bv.data[2] & 0xFF);
        assertEquals('e', bv.data[3] & 0xFF);
    }

    @Test
    public void testPutUTF8NonAscii() {
        String s = "hé"; // contains non-ASCII character
        ByteVector bv = new ByteVector(10);
        bv.putUTF8(s);
        assertTrue(bv.length >= 4);
        assertEquals(0, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutByteArrayWithinCapacity() {
        ByteVector bv = new ByteVector(10);
        byte[] arr = {1, 2, 3};
        bv.putByteArray(arr, 0, 3);
        assertEquals(3, bv.length);
        assertEquals(1, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutByteArrayWithNull() {
        ByteVector bv = new ByteVector(5);
        bv.putByteArray(null, 0, 2);
        assertEquals(0, bv.length);
        assertArrayEquals(new byte[0], bv.data);
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
