import static org.junit.Assert.*;
import org.junit.Test;

public class CharRangeTest {

    @Test
    public void testIsSingleCharRange() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotSingleCharRange() {
        CharRange range = CharRange.isNot('b');
        assertEquals('b', range.getStart());
        assertEquals('b', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testIsInRange() {
        CharRange range = CharRange.isIn('a', 'e');
        assertEquals('a', range.getStart());
        assertEquals('e', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsNotInRange() {
        CharRange range = CharRange.isNotIn('x', 'z');
        assertEquals('x', range.getStart());
        assertEquals('z', range.getEnd());
        assertTrue(range.isNegated());
    }

    @Test
    public void testOrderReversal() {
        CharRange range = CharRange.isIn('z', 'a');
        assertEquals('a', range.getStart());
        assertEquals('z', range.getEnd());
        assertFalse(range.isNegated());
    }

    @Test
    public void testContainsCharacterInside() {
        CharRange range = CharRange.isIn('a', 'd');
        assertTrue(range.contains('b'));
    }

    @Test
    public void testContainsCharacterOutsideNegated() {
        CharRange range = CharRange.isIn('a', 'd');
        assertFalse(range.contains('f'));
    }

    @Test
    public void testContainsCharacterInsideNegated() {
        CharRange range = CharRange.isNotIn('a', 'd');
        assertFalse(range.contains('a'));
        assertFalse(range.contains('b'));
        assertFalse(range.contains('c'));
        assertFalse(range.contains('d'));
        assertTrue(range.contains('e'));
    }

    @Test
    public void testContainsRangeWithin() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('c', 'f');
        assertTrue(outer.contains(inner));
    }

    @Test
    public void testContainsRangeOutsideNegated() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange insideNegated = CharRange.isNotIn('c', 'f');
        assertFalse(outer.contains(insideNegated));
    }

    @Test
    public void testContainsNegatedRange() {
        CharRange negRange = CharRange.isNotIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'c');
        assertFalse(negRange.contains(inner));
    }

    @Test
    public void testEqualsSelf() {
        CharRange range = CharRange.isIn('a', 'b');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEqualsIdentical() {
        CharRange range1 = CharRange.isIn('a', 'd');
        CharRange range2 = CharRange.isIn('a', 'd');
        assertTrue(range1.equals(range2));
    }

    @Test
    public void testEqualsDifferent() {
        CharRange range1 = CharRange.isIn('a', 'd');
        CharRange range2 = CharRange.isIn('a', 'e');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testEqualsDifferentNegation() {
        CharRange range1 = CharRange.isIn('a', 'd');
        CharRange range2 = CharRange.isNotIn('a', 'd');
        assertFalse(range1.equals(range2));
    }

    @Test
    public void testHashCodeConsistency() {
        CharRange range = CharRange.isIn('x', 'z');
        int hash1 = range.hashCode();
        int hash2 = range.hashCode();
        assertEquals(hash1, hash2);
    }

    @Test
    public void testToStringPositiveRange() {
        CharRange range = CharRange.isIn('a', 'c');
        String expected = "a-c";
        assertEquals(expected, range.toString());
    }

    @Test
    public void testToStringNegatedRange() {
        CharRange range = CharRange.isNotIn('a', 'c');
        String expected = "^a-c";
        assertEquals(expected, range.toString());
    }
}

