import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testPutByte() {
        ByteVector bv = new ByteVector();
        bv.putByte(10);
        assertEquals(1, bv.length);
        assertEquals(10, bv.data[0] & 0xFF);
    }

    @Test
    public void testPutByteEnlarges() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1);
        bv.putByte(2);
        assertTrue(bv.length >= 2);
        assertEquals(1, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut11() {
        ByteVector bv = new ByteVector();
        bv.put11(5, 10);
        assertEquals(2, bv.length);
        assertEquals(5, bv.data[0] & 0xFF);
        assertEquals(10, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut11Enlarge() {
        ByteVector bv = new ByteVector(1);
        bv.put11(1, 2);
        assertTrue(bv.length >= 2);
        assertEquals(1, bv.data[0] & 0xFF);
        assertEquals(2, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShort() {
        ByteVector bv = new ByteVector();
        int s = 0x1234;
        bv.putShort(s);
        assertEquals(2, bv.length);
        assertEquals(0x12, bv.data[0] & 0xFF);
        assertEquals(0x34, bv.data[1] & 0xFF);
    }

    @Test
    public void testPutShortEnlarge() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0xABCD);
        assertTrue(bv.length >= 2);
        assertEquals(0xAB, bv.data[0] & 0xFF);
        assertEquals(0xCD, bv.data[1] & 0xFF);
    }

    @Test
    public void testPut12() {
        ByteVector bv = new ByteVector();
        bv.put12(0xA, 0xBEEF);
        assertEquals(3, bv.length);
        assertEquals(0xA, bv.data[0] & 0xFF);
        assertEquals((byte) 0xBE, bv.data[1]);
        assertEquals((byte) 0xEF, bv.data[2]);
    }

    @Test
    public void testPut12Enlarge() {
        ByteVector bv = new ByteVector(2);
        bv.put12(0x1, 0x1234);
        assertTrue(bv.length >= 3);
        assertEquals(0x1, bv.data[0] & 0xFF);
        assertEquals(0x12, bv.data[1] & 0xFF);
        assertEquals(0x34, bv.data[2] & 0xFF);
    }

    @Test
    public void testPutInt() {
        ByteVector bv = new ByteVector();
        int i = 0x11223344;
        bv.putInt(i);
        assertEquals(4, bv.length);
        assertEquals(0x11, bv.data[0] & 0xFF);
        assertEquals(0x22, bv.data[1] & 0xFF);
        assertEquals(0x33, bv.data[2] & 0xFF);
        assertEquals(0x44, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutIntEnlarge() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0xAABBCCDD);
        assertTrue(bv.length >= 4);
        assertEquals(0xAA, bv.data[0] & 0xFF);
        assertEquals(0xBB, bv.data[1] & 0xFF);
        assertEquals(0xCC, bv.data[2] & 0xFF);
        assertEquals(0xDD, bv.data[3] & 0xFF);
    }

    @Test
    public void testPutLong() {
        ByteVector bv = new ByteVector();
        long l = 0x0102030405060708L;
        bv.putLong(l);
        assertEquals(8, bv.length);
        assertEquals(0x01, bv.data[0] & 0xFF);
        assertEquals(0x02, bv.data[1] & 0xFF);
        assertEquals(0x03, bv.data[2] & 0xFF);
        assertEquals(0x04, bv.data[3] & 0xFF);
        assertEquals(0x05, bv.data[4] & 0xFF);
        assertEquals(0x06, bv.data[5] & 0xFF);
        assertEquals(0x07, bv.data[6] & 0xFF);
        assertEquals(0x08, bv.data[7] & 0xFF);
    }

    @Test
    public void testPutUTF8Simple() {
        String s = "abc";
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length >= s.length() + 2);
        assertEquals(0, bv.data[0] & 0xFF);
        assertEquals(3, bv.data[1] & 0xFF);
        assertEquals('a', bv.data[2] & 0xFF);
        assertEquals('b', bv.data[3] & 0xFF);
        assertEquals('c', bv.data[4] & 0xFF);
    }

    @Test
    public void testPutUTF8WithNonASCII() {
        String s = "a\u07FF\u8000"; // includes characters requiring multi-byte
        ByteVector bv = new ByteVector();
        bv.putUTF8(s);
        assertTrue(bv.length >= s.length() + 2);
        // The length bytes should be correct
        int lenHigh = bv.data[0] & 0xFF;
        int lenLow = bv.data[1] & 0xFF;
        int lengthInData = (lenHigh << 8) | lenLow;
        assertTrue(lengthInData <= bv.length - 2);
    }

    @Test
    public void testPutByteArray() {
        byte[] b = {1, 2, 3, 4, 5};
        ByteVector bv = new ByteVector();
        bv.putByteArray(b, 1, 3);
        assertEquals(3, bv.length);
        assertEquals(2, bv.data[0] & 0xFF);
        assertEquals(3, bv.data[1] & 0xFF);
        assertEquals(4, bv.data[2] & 0xFF);
    }

    @Test
    public void testEnlarge() {
        ByteVector bv = new ByteVector(1);
        int initialCapacity = bv.data.length;
        bv.putByte(1);
        bv.enlarge(10);
        assertTrue(bv.data.length >= initialCapacity * 2);
    }
}

/**
 * <p>A contiguous range of characters, optionally negated.</p>
 * 
 * <p>Instances are immutable.</p>
 */
public class CharRange {

    /** The first character, inclusive, in the range. */
    private final char start;
    /** The last character, inclusive, in the range. */
    private final char end;
    /** True if the range is everything except the characters specified. */
    private final boolean negated;

    /** Cached toString. */
    private transient String iToString;

    /**
     * <p>Constructs a {@code CharRange} over a set of characters,
     * optionally negating the range.</p>
     *
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     * 
     * <p>If start and end are in the wrong order, they are reversed.
     * Thus {@code a-e} is the same as {@code e-a}.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @param negated  true to express everything except the range
     */
    private CharRange(char start, char end, final boolean negated) {
        super();
        if (start > end) {
            final char temp = start;
            start = end;
            end = temp;
        }

        this.start = start;
        this.end = end;
        this.negated = negated;
    }

    /**
     * <p>Constructs a {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange is(final char ch) {
        return new CharRange(ch, ch, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNot(final char ch) {
        return new CharRange(ch, ch, true);
    }

    /**
     * <p>Constructs a {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isIn(final char start, final char end) {
        return new CharRange(start, end, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testSingleCharacterInRange() {
        CharRange range = CharRange.is('a');
        assertTrue(range.contains('a'));
        assertFalse(range.contains('b'));
    }

    @Test
    public void testSingleCharacterNegated() {
        CharRange range = CharRange.isNot('a');
        assertFalse(range.contains('a'));
        assertTrue(range.contains('b'));
    }

    @Test
    public void testRangeInRange() {
        CharRange range = CharRange.isIn('a', 'e');
        assertTrue(range.contains('a'));
        assertTrue(range.contains('c'));
        assertTrue(range.contains('e'));
        assertFalse(range.contains('f'));
    }

    @Test
    public void testRangeNegatedInRange() {
        CharRange range = CharRange.isNotIn('a', 'e');
        assertFalse(range.contains('a'));
        assertFalse(range.contains('c'));
        assertFalse(range.contains('e'));
        assertTrue(range.contains('f'));
    }

    @Test
    public void testRangeWithReverseOrder() {
        CharRange range1 = CharRange.isIn('a', 'e');
        CharRange range2 = CharRange.isIn('e', 'a');
        assertEquals(range1, range2);
        assertTrue(range1.contains('a'));
        assertTrue(range2.contains('a'));
    }

    @Test
    public void testEqualsSameObject() {
        CharRange range = CharRange.is('a');
        assertTrue(range.equals(range));
    }

    @Test
    public void testEqualsDifferentObject() {
        CharRange range1 = CharRange.is('a');
        CharRange range2 = CharRange.is('a');
        assertTrue(range1.equals(range2));
        CharRange range3 = CharRange.is('b');
        assertFalse(range1.equals(range3));
        assertFalse(range1.equals(null));
        assertFalse(range1.equals("not a CharRange"));
    }

    @Test
    public void testHashCodeConsistency() {
        CharRange range = CharRange.is('a');
        int hash1 = range.hashCode();
        int hash2 = range.hashCode();
        assertEquals(hash1, hash2);
    }

    @Test
    public void testToStringNonNegatedSingleChar() {
        CharRange range = CharRange.is('x');
        String str = range.toString();
        assertEquals("x", str);
    }

    @Test
    public void testToStringNegatedSingleChar() {
        CharRange range = CharRange.isNot('x');
        String str = range.toString();
        assertEquals("^x", str);
    }

    @Test
    public void testToStringRange() {
        CharRange range = CharRange.isIn('a', 'f');
        String str = range.toString();
        assertEquals("a-f", str);
    }

    @Test
    public void testContainsRangeWithinRange() {
        CharRange range = CharRange.isIn('a', 'z');
        CharRange subRange = CharRange.isIn('b', 'y');
        assertTrue(range.contains(subRange));
    }

    @Test
    public void testContainsRangeOutsideNegatedRange() {
        CharRange range = CharRange.isNotIn('a', 'z');
        CharRange outsideRange = CharRange.isIn('a', 'z');
        assertFalse(range.contains(outsideRange));
    }

    @Test
    public void testContainsRangeNegatedContainsRange() {
        CharRange range = CharRange.isNotIn('a', 'z');
        CharRange insideRange = CharRange.isIn('b', 'y');
        assertTrue(range.contains(insideRange));
    }

}

