     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;

import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterAccessorsAndNegation() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertFalse(range.isNegated());
    }

    @Test
    public void testIsSingleCharacterEndAndContains() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getEnd());
        assertTrue(range.contains('a'));
    }

    @Test
    public void testIsNotSingleCharacterContainsInversion() {
        CharRange range = CharRange.isNot('a');
        assertFalse(range.contains('a'));
        assertTrue(range.contains('b'));
    }

    @Test
    public void testIsInReversesOrderForAccessors() {
        CharRange range = CharRange.isIn('e', 'a');
        assertEquals('a', range.getStart());
        assertEquals('e', range.getEnd());
    }

    @Test
    public void testIsInContainsBoundariesAndOutside() {
        CharRange range = CharRange.isIn('a', 'e');
        assertTrue(range.contains('a'));
        assertFalse(range.contains('f'));
    }

    @Test
    public void testIsNotInNegatedContainsInsideAndOutside() {
        CharRange range = CharRange.isNotIn('a', 'e');
        assertFalse(range.contains('c'));
        assertTrue(range.contains('z'));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContainsRangeNullThrows() {
        CharRange.is('a').contains((CharRange) null);
    }

    @Test
    public void testContainsRangeNonNegatedContainsNonNegatedTrue() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('c', 'm');
        assertTrue(outer.contains(inner));
        assertFalse(inner.contains(outer));
    }

    @Test
    public void testContainsRangeNonNegatedCannotContainNegatedUnlessFullRange() {
        CharRange r = CharRange.isIn('a', 'z');
        CharRange neg = CharRange.isNotIn('c', 'm');
        assertFalse(r.contains(neg));
        assertTrue(CharRange.isIn((char) 0, Character.MAX_VALUE).contains(neg));
    }

    @Test
    public void testContainsRangeNegatedContainsNonNegatedWhenDisjointFromExcluded() {
        CharRange neg = CharRange.isNotIn('c', 'm');
        assertTrue(neg.contains(CharRange.isIn('a', 'b')));
        assertFalse(neg.contains(CharRange.isIn('b', 'd')));
    }

    @Test
    public void testContainsRangeNegatedContainsNegatedWhenExcludedSubset() {
        CharRange outerNeg = CharRange.isNotIn('c', 'm');
        CharRange innerNeg = CharRange.isNotIn('e', 'g');
        assertTrue(outerNeg.contains(innerNeg));
        assertFalse(innerNeg.contains(outerNeg));
    }

    @Test
    public void testEqualsAndHashCodeSameValues() {
        CharRange a = CharRange.isNotIn('a', 'e');
        CharRange b = CharRange.isNotIn('a', 'e');
        assertTrue(a.equals(b));
        assertEquals(a.hashCode(), b.hashCode());
    }

    @Test
    public void testEqualsDifferentNegationNotEqual() {
        CharRange a = CharRange.isIn('a', 'e');
        CharRange b = CharRange.isNotIn('a', 'e');
        assertFalse(a.equals(b));
        assertFalse(a.equals("not a range"));
    }

    @Test
    public void testEqualsSameInstanceTrue() {
        CharRange a = CharRange.isIn('a', 'e');
        assertTrue(a.equals(a));
        assertFalse(a.equals(null));
    }

    @Test
    public void testToStringNonNegatedSingleAndRange() {
        assertEquals("a", CharRange.is('a').toString());
        assertEquals("a-e", CharRange.isIn('a', 'e').toString());
    }

    @Test
    public void testToStringNegatedSingleAndRange() {
        assertEquals("^a", CharRange.isNot('a').toString());
        assertEquals("^a-e", CharRange.isNotIn('a', 'e').toString());
    }

    @Test
    public void testToStringCacheReturnsSameReferenceOnSecondCall() {
        CharRange range = CharRange.isNotIn('a', 'e');
        String s1 = range.toString();
        String s2 = range.toString();
        assertSame(s1, s2);
        assertEquals("^a-e", s2);
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() {
        ByteVector bv = new ByteVector();
        assertEquals(0, bv.length);
        assertEquals(64, bv.data.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector bv = new ByteVector(3);
        assertEquals(0, bv.length);
        assertEquals(3, bv.data.length);
    }

    @Test
    public void testPutByteWritesAndIncrementsLength() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(0xAB);
        assertEquals(1, bv.length);
        assertEquals((byte) 0xAB, bv.data[0]);
    }

    @Test
    public void testPutByteEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPut11WritesTwoBytes() {
        ByteVector bv = new ByteVector(2);
        bv.put11(0x12, 0xFE);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0x12, (byte) 0xFE }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPut11EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPutShortBigEndian() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPutShortEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0x0102);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPut12WritesByteThenShort() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0x7F, 0x0102);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0x7F, 0x01, 0x02 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void testPut12EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.put12(1, 2);
        assertEquals(3, bv.length);
        assertTrue(bv.data.length >= 3);
    }

    @Test
    public void testPutIntBigEndian() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void testPutIntEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertTrue(bv.data.length >= 4);
    }

    @Test
    public void testPutLongBigEndian() {
        ByteVector bv = new ByteVector(8);
        bv.putLong(0x0102030405060708L);
        assertEquals(8, bv.length);
        assertArrayEquals(
                new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 },
                new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4], bv.data[5], bv.data[6], bv.data[7] }
        );
    }

    @Test
    public void testPutLongEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(7);
        bv.putLong(0L);
        assertEquals(8, bv.length);
        assertTrue(bv.data.length >= 8);
    }

    @Test
    public void testPutUTF8AsciiString() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("ABC");
        assertEquals(5, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x03, 0x41, 0x42, 0x43 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4] });
    }

    @Test
    public void testPutUTF8TwoByteChar() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u00A2"); // ¢ -> C2 A2
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC2, (byte) 0xA2 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void testPutUTF8ThreeByteChar() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u20AC"); // € -> E2 82 AC
        assertEquals(5, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x03, (byte) 0xE2, (byte) 0x82, (byte) 0xAC }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4] });
    }

    @Test
    public void testPutUTF8EnlargesDuringGeneralEncoding() {
        ByteVector bv = new ByteVector(3);
        bv.putByte(0x11).putUTF8("\u20AC"); // requires 1 + 2 + 3 = 6 bytes total
        assertEquals(6, bv.length);
        assertTrue(bv.data.length >= 6);
    }

    @Test
    public void testPutByteArrayCopiesBytes() {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(new byte[] { 9, 8, 7, 6 }, 1, 2);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 8, 7 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void testPutByteArrayWithNullWritesZeros() {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(null, 0, 3);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0, 0, 0 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void testPutByteArrayEnlargesWhenNeededAndPreservesExistingData() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(0x55).putByteArray(new byte[] { 1, 2, 3 }, 0, 3);
        assertEquals(4, bv.length);
        assertEquals((byte) 0x55, bv.data[0]);
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;

import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void defaultConstructorInitialCapacityIs64AndLengthIs0() {
        ByteVector v = new ByteVector();
        assertEquals(64, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void intConstructorSetsInitialCapacityAndLengthIs0() {
        ByteVector v = new ByteVector(3);
        assertEquals(3, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void putByteWritesByteAndIncrementsLength() {
        ByteVector v = new ByteVector(1);
        v.putByte(0xAB);
        assertEquals(1, v.length);
        assertEquals((byte) 0xAB, v.data[0]);
    }

    @Test
    public void putByteEnlargesWhenFull() {
        ByteVector v = new ByteVector(1);
        v.putByte(1).putByte(2);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void put11WritesTwoBytesInOrder() {
        ByteVector v = new ByteVector(2);
        v.put11(0x11, 0x22);
        assertArrayEquals(new byte[] { 0x11, 0x22 }, new byte[] { v.data[0], v.data[1] });
        assertEquals(2, v.length);
    }

    @Test
    public void put11EnlargesWhenNeeded() {
        ByteVector v = new ByteVector(1);
        v.put11(0x11, 0x22);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void putShortWritesBigEndian() {
        ByteVector v = new ByteVector(2);
        v.putShort(0x1234);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { v.data[0], v.data[1] });
        assertEquals(2, v.length);
    }

    @Test
    public void putShortEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(1);
        v.putShort(0x0001);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void put12WritesByteThenShort() {
        ByteVector v = new ByteVector(3);
        v.put12(0x7F, 0x1234);
        assertArrayEquals(new byte[] { 0x7F, 0x12, 0x34 }, new byte[] { v.data[0], v.data[1], v.data[2] });
        assertEquals(3, v.length);
    }

    @Test
    public void put12EnlargesWhenNeeded() {
        ByteVector v = new ByteVector(2);
        v.put12(0x01, 0x0203);
        assertTrue(v.data.length >= 3);
        assertEquals(3, v.length);
    }

    @Test
    public void putIntWritesBigEndian() {
        ByteVector v = new ByteVector(4);
        v.putInt(0x01020304);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
        assertEquals(4, v.length);
    }

    @Test
    public void putIntEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(3);
        v.putInt(0x01020304);
        assertTrue(v.data.length >= 4);
        assertEquals(4, v.length);
    }

    @Test
    public void putLongWritesBigEndian() {
        ByteVector v = new ByteVector(8);
        v.putLong(0x0102030405060708L);
        assertArrayEquals(
                new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4], v.data[5], v.data[6], v.data[7] }
        );
        assertEquals(8, v.length);
    }

    @Test
    public void putLongEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(7);
        v.putLong(0L);
        assertTrue(v.data.length >= 8);
        assertEquals(8, v.length);
    }

    @Test
    public void putUTF8AsciiWritesLengthPrefixAndBytes() {
        ByteVector v = new ByteVector(5);
        v.putUTF8("ABC");
        assertArrayEquals(new byte[] { 0x00, 0x03, 0x41, 0x42, 0x43 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
        assertEquals(5, v.length);
    }

    @Test
    public void putUTF8TwoByteCharacterEncodesCorrectly() {
        ByteVector v = new ByteVector(4);
        v.putUTF8("\u0080");
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC2, (byte) 0x80 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
        assertEquals(4, v.length);
    }

    @Test
    public void putUTF8ThreeByteCharacterEncodesCorrectly() {
        ByteVector v = new ByteVector(5);
        v.putUTF8("\u0800");
        assertArrayEquals(new byte[] { 0x00, 0x03, (byte) 0xE0, (byte) 0xA0, (byte) 0x80 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
        assertEquals(5, v.length);
    }

    @Test
    public void putUTF8NullCharIsEncodedAsTwoBytesAndLengthPrefixAdjusted() {
        ByteVector v = new ByteVector(4);
        v.putUTF8("\u0000");
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC0, (byte) 0x80 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
        assertEquals(4, v.length);
    }

    @Test
    public void putUTF8EnlargesWhenInitialCapacityTooSmallForActualEncoding() {
        ByteVector v = new ByteVector(3);
        v.putUTF8("\u0000");
        assertTrue(v.data.length >= 4);
        assertEquals(4, v.length);
    }

    @Test
    public void putByteArrayCopiesBytesAtOffset() {
        ByteVector v = new ByteVector(3);
        byte[] src = new byte[] { 9, 8, 7, 6 };
        v.putByteArray(src, 1, 2);
        assertArrayEquals(new byte[] { 8, 7 }, new byte[] { v.data[0], v.data[1] });
        assertEquals(2, v.length);
    }

    @Test
    public void putByteArrayWithNullWritesZeros() {
        ByteVector v = new ByteVector(2);
        v.putByteArray(null, 0, 2);
        assertArrayEquals(new byte[] { 0, 0 }, new byte[] { v.data[0], v.data[1] });
        assertEquals(2, v.length);
    }

    @Test
    public void putByteArrayEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(1);
        v.putByteArray(new byte[] { 1, 2, 3 }, 0, 3);
        assertTrue(v.data.length >= 3);
        assertEquals(3, v.length);
    }

    @Test
    public void chainingMethodsReturnSameInstance() {
        ByteVector v = new ByteVector(1);
        ByteVector r = v.putByte(1).putShort(2);
        assertSame(v, r);
        assertEquals(3, v.length);
    }
}

