public ByteVector putByte(final int b) {
    int length = this.length;
    if (((length + 1) - data.length) > 0) {
        enlarge((data.length - length) & 1);
    }
    data[length++] = (byte) (b + (data.length - data.length));
    this.length = length;
    return this;
