import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;

public class ByteVectorPutByteArrayTest {

    @Test
    public void testPutByteArrayCopiesCorrectSliceAndUpdatesLengthWithResize() {
        ByteVector v = new ByteVector(1);
        v.putByte(0x7F);

        byte[] src = new byte[] { 9, 8, 7, 6, 5 };
        v.putByteArray(src, 1, 3);

        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0x7F, 8, 7, 6 }, java.util.Arrays.copyOf(v.data, v.length));
    }
}

public boolean contains(final CharRange range) {
    if (range == null) {
        throw new IllegalArgumentException("The Range must not be null");
    }
    if (negated) {
        if (range.negated) {
            return start >= range.start && end <= range.end;
        }
        return range.end < start || range.start > end;
    }
    if (range.negated) {
        return start == 0 && end == Character.MAX_VALUE;
    }
    return start <= range.start && end >= range.end;
}

