public class ByteVectorPutByteArrayTest {

    @Test
    void putByteArray_copiesCorrectSlice_andAdvancesLength_andEnlarges() {
        ByteVector v = new ByteVector(1);
        v.putByte(0x7F);

        byte[] src = new byte[] { 9, 8, 7, 6, 5 };
        v.putByteArray(src, 2, 3); // copies {7,6,5} starting at index 1 in data

        assertArrayEquals(new byte[] { 0x7F, 7, 6, 5 }, java.util.Arrays.copyOf(v.data, v.length));
        assertEquals(4, v.length);
    }
}

