import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedAsciiTwoByteAndThreeByteAndFixesLengthPrefix() {
        ByteVector bv = new ByteVector(3); // force enlarge path
        String s = "A\u0000\u0080\u0800";   // ASCII, 2-byte (NUL), 2-byte, 3-byte

        bv.putUTF8(s);

        byte[] expected = new byte[] {
                0x00, 0x08,                         // UTF8 byte length = 8
                0x41,                               // 'A'
                (byte) 0xC0, (byte) 0x80,           // U+0000
                (byte) 0xC2, (byte) 0x80,           // U+0080
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80 // U+0800
        };

        byte[] actual = new byte[bv.length];
        System.arraycopy(bv.data, 0, actual, 0, bv.length);

        assertArrayEquals(expected, actual);
    }
}

