        bv.putLong(v);

        assertArrayEquals(
                new byte[] { 0x01, 0x02, 0x03, 0x04, (byte) 0xA0, (byte) 0xB0, (byte) 0xC0, (byte) 0xD0 },
                java.util.Arrays.copyOf(bv.data, bv.length)
        );
        assertEquals(8, bv.length);
