public class CharRangeContainsRangeTest {

    @Test
    public void testContainsRangeNegatedVsNonNegatedAndTotalRange() {
        CharRange negated = CharRange.isNotIn('c', 'f');          // everything except c-f
        CharRange nonNegOutside = CharRange.isIn('a', 'b');       // wholly outside excluded region
        CharRange nonNegOverlaps = CharRange.isIn('b', 'd');      // overlaps excluded region
        CharRange total = CharRange.isIn((char) 0, Character.MAX_VALUE);

        assertAll(
                () -> assertTrue(negated.contains(nonNegOutside)),
                () -> assertFalse(negated.contains(nonNegOverlaps)),
                () -> assertTrue(total.contains(CharRange.isNot('x')))
        );
    }
}

