public class ByteVectorPutLongTest {

    @Test
    void putLong_writesBigEndianAndAdvancesLengthFromNonZeroOffset() {
        ByteVector bv = new ByteVector(8);
        bv.putInt(0xA1B2C3D4);
        bv.putLong(0x0102030405060708L);

        assertEquals(12, bv.length);

        assertArrayEquals(
                new byte[] {
                        (byte) 0xA1, (byte) 0xB2, (byte) 0xC3, (byte) 0xD4,
                        0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08
                },
                java.util.Arrays.copyOf(bv.data, bv.length)
        );
    }
