import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_mixedAsciiTwoAndThreeByteChars_correctLengthPrefixAndBytes() {
        ByteVector bv = new ByteVector(2);
        String s = "A\u0080\u0800B"; // 'A' (1 byte), U+0080 (2 bytes), U+0800 (3 bytes), 'B' (1 byte)
        bv.putUTF8(s);

        byte[] utf8 = s.getBytes(StandardCharsets.UTF_8);
        byte[] expected = new byte[2 + utf8.length];
        expected[0] = (byte) (utf8.length >>> 8);
        expected[1] = (byte) utf8.length;
        System.arraycopy(utf8, 0, expected, 2, utf8.length);

        assertEquals(expected.length, bv.length);
        assertArrayEquals(expected, java.util.Arrays.copyOf(bv.data, bv.length));
    }
}

