        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;

import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void defaultConstructorInitialCapacityAndLength() {
        ByteVector v = new ByteVector();
        assertEquals(0, v.length);
        assertEquals(64, v.data.length);
    }

    @Test
    public void sizedConstructorInitialCapacityAndLength() {
        ByteVector v = new ByteVector(3);
        assertEquals(0, v.length);
        assertEquals(3, v.data.length);
    }

    @Test
    public void putByteWritesSingleByteAndAdvancesLength() {
        ByteVector v = new ByteVector(1);
        v.putByte(0xAB);
        assertEquals(1, v.length);
        assertEquals((byte) 0xAB, v.data[0]);
    }

    @Test
    public void putByteEnlargesWhenFullAndPreservesExistingData() {
        ByteVector v = new ByteVector(1);
        v.putByte(1).putByte(2);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 1, 2 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void put11WritesTwoBytesInOrder() {
        ByteVector v = new ByteVector(2);
        v.put11(0x01, 0xFF);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 1, (byte) 0xFF }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void put11EnlargesWhenNeeded() {
        ByteVector v = new ByteVector(1);
        v.put11(0x7E, 0x7F);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0x7E, 0x7F }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void putShortWritesBigEndian() {
        ByteVector v = new ByteVector(2);
        v.putShort(0x1234);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void put12WritesByteThenShortBigEndian() {
        ByteVector v = new ByteVector(3);
        v.put12(0xFE, 0x0102);
        assertEquals(3, v.length);
        assertArrayEquals(new byte[] { (byte) 0xFE, 0x01, 0x02 }, new byte[] { v.data[0], v.data[1], v.data[2] });
    }

    @Test
    public void putIntWritesBigEndian() {
        ByteVector v = new ByteVector(4);
        v.putInt(0x01020304);
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 1, 2, 3, 4 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void putLongWritesBigEndian() {
        ByteVector v = new ByteVector(8);
        v.putLong(0x0102030405060708L);
        assertEquals(8, v.length);
        assertArrayEquals(
                new byte[] { 1, 2, 3, 4, 5, 6, 7, 8 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4], v.data[5], v.data[6], v.data[7] }
        );
    }

    @Test
    public void putUTF8AsciiEncodesLengthAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("ABC");
        assertEquals(5, v.length);
        assertArrayEquals(new byte[] { 0, 3, 'A', 'B', 'C' }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
    }

    @Test
    public void putUTF8TwoByteCharEncodesUtf8LengthAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u00A2"); // ¢ -> C2 A2
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0, 2, (byte) 0xC2, (byte) 0xA2 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void putUTF8ThreeByteCharEncodesUtf8LengthAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u20AC"); // € -> E2 82 AC
        assertEquals(5, v.length);
        assertArrayEquals(new byte[] { 0, 3, (byte) 0xE2, (byte) 0x82, (byte) 0xAC }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
    }

    @Test
    public void putUTF8EnlargesAndRewritesLengthForNonAscii() {
        ByteVector v = new ByteVector(3);
        v.putUTF8("\u00A2"); // needs 4 bytes total
        assertTrue(v.data.length >= 4);
        assertEquals(4, v.length);
    }

    @Test
    public void putByteArrayCopiesBytesAndAdvancesLength() {
        ByteVector v = new ByteVector(10);
        byte[] src = new byte[] { 10, 11, 12, 13, 14 };
        v.putByteArray(src, 1, 3);
        assertEquals(3, v.length);
        assertArrayEquals(new byte[] { 11, 12, 13 }, new byte[] { v.data[0], v.data[1], v.data[2] });
    }

    @Test
    public void putByteArrayWithNullInsertsZerosAndAdvancesLength() {
        ByteVector v = new ByteVector(10);
        v.putByte(9);
        v.putByteArray(null, 0, 3);
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 9, 0, 0, 0 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void putByteArrayEnlargesToFitAndPreservesExistingData() {
        ByteVector v = new ByteVector(2);
        v.putByte(1);
        v.putByteArray(new byte[] { 2, 3, 4 }, 0, 3);
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 1, 2, 3, 4 }, new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void chainingReturnsSameInstance() {
        ByteVector v = new ByteVector(1);
        ByteVector returned = v.putByte(1).putShort(2);
        assertSame(v, returned);
        assertEquals(3, v.length);
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;

import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void defaultConstructorInitializesDataTo64AndLengthTo0() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void constructorWithInitialSizeSetsArrayLengthAndZeroLength() {
        ByteVector bv = new ByteVector(3);
        assertEquals(3, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void putByteAppendsAndIncrementsLength() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0x7F);
        assertEquals(1, bv.length);
        assertEquals((byte) 0x7F, bv.data[0]);
    }

    @Test
    public void putByteEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void put11WritesTwoBytesInOrder() {
        ByteVector bv = new ByteVector(2);
        bv.put11(0x01, 0xFF);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { (byte) 0x01, (byte) 0xFF }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void put11EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.put11(1, 2);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void putShortWritesBigEndian() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void putShortEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(1);
        bv.putShort(0x1234);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void put12WritesByteThenShortBigEndian() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0x7F, 0x0102);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0x7F, 0x01, 0x02 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void put12EnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.put12(1, 2);
        assertEquals(3, bv.length);
        assertTrue(bv.data.length >= 3);
    }

    @Test
    public void putIntWritesBigEndian() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void putIntEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0x01020304);
        assertEquals(4, bv.length);
        assertTrue(bv.data.length >= 4);
    }

    @Test
    public void putLongWritesBigEndian() {
        ByteVector bv = new ByteVector(8);
        bv.putLong(0x0102030405060708L);
        assertEquals(8, bv.length);
        assertArrayEquals(
                new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 },
                new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4], bv.data[5], bv.data[6], bv.data[7] }
        );
    }

    @Test
    public void putLongEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(7);
        bv.putLong(0L);
        assertEquals(8, bv.length);
        assertTrue(bv.data.length >= 8);
    }

    @Test
    public void putUTF8AsciiWritesLengthPrefixAndBytes() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("Hi");
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 'H', (byte) 'i' }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void putUTF8TwoByteEncodingAndByteLengthPrefix() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("é"); // U+00E9 -> C3 A9
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC3, (byte) 0xA9 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }

    @Test
    public void putUTF8ThreeByteEncodingAndByteLengthPrefix() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("अ"); // U+0905 -> E0 A4 85
        assertEquals(5, bv.length);
        assertArrayEquals(new byte[] { 0x00, 0x03, (byte) 0xE0, (byte) 0xA4, (byte) 0x85 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3], bv.data[4] });
    }

    @Test
    public void putUTF8EnlargesWhenDefaultAssumptionFailsAfterWritingSomeAscii() {
        ByteVector bv = new ByteVector(4);
        bv.putUTF8("Aé"); // optimistic writes 2+2 then detects needs 2+3
        assertEquals(5, bv.length);
        assertTrue(bv.data.length >= 5);
    }

    @Test
    public void putByteArrayCopiesBytesAndUpdatesLength() {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(new byte[] { 1, 2, 3, 4 }, 1, 2);
        assertEquals(2, bv.length);
        assertArrayEquals(new byte[] { 2, 3 }, new byte[] { bv.data[0], bv.data[1] });
    }

    @Test
    public void putByteArrayWithNullWritesZerosAndUpdatesLength() {
        ByteVector bv = new ByteVector(10);
        bv.putByteArray(null, 0, 3);
        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { 0, 0, 0 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
    }

    @Test
    public void putByteArrayEnlargesWhenNeededAndPreservesExistingData() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(9);
        bv.putByteArray(new byte[] { 1, 2, 3 }, 0, 3);
        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 9, 1, 2, 3 }, new byte[] { bv.data[0], bv.data[1], bv.data[2], bv.data[3] });
    }
}

/**
 * <p>A contiguous range of characters, optionally negated.</p>
 * 
 * <p>Instances are immutable.</p>
 */
public class CharRange {

    /** The first character, inclusive, in the range. */
    private final char start;
    /** The last character, inclusive, in the range. */
    private final char end;
    /** True if the range is everything except the characters specified. */
    private final boolean negated;

    /** Cached toString. */
    private transient String iToString;

    /**
     * <p>Constructs a {@code CharRange} over a set of characters,
     * optionally negating the range.</p>
     *
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     * 
     * <p>If start and end are in the wrong order, they are reversed.
     * Thus {@code a-e} is the same as {@code e-a}.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @param negated  true to express everything except the range
     */
    private CharRange(char start, char end, final boolean negated) {
        super();
        if (start > end) {
            final char temp = start;
            start = end;
            end = temp;
        }

        this.start = start;
        this.end = end;
        this.negated = negated;
    }

    /**
     * <p>Constructs a {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange is(final char ch) {
        return new CharRange(ch, ch, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNot(final char ch) {
        return new CharRange(ch, ch, true);
    }

    /**
     * <p>Constructs a {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isIn(final char start, final char end) {
        return new CharRange(start, end, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterBasics() {
        CharRange range = CharRange.is('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
    }

    @Test
    public void testIsSingleCharacterNegationFlag() {
        CharRange range = CharRange.is('a');
        assertFalse(range.isNegated());
        assertTrue(range.contains('a'));
    }

    @Test
    public void testIsNotSingleCharacterBasics() {
        CharRange range = CharRange.isNot('a');
        assertEquals('a', range.getStart());
        assertEquals('a', range.getEnd());
    }

    @Test
    public void testIsNotSingleCharacterContains() {
        CharRange range = CharRange.isNot('a');
        assertTrue(range.isNegated());
        assertFalse(range.contains('a'));
    }

    @Test
    public void testIsInReversesOrder() {
        CharRange range = CharRange.isIn('e', 'a');
        assertEquals('a', range.getStart());
        assertEquals('e', range.getEnd());
    }

    @Test
    public void testIsInContainsBoundsAndOutside() {
        CharRange range = CharRange.isIn('a', 'c');
        assertTrue(range.contains('a'));
        assertFalse(range.contains('d'));
    }

    @Test
    public void testIsNotInReversesOrderAndNegated() {
        CharRange range = CharRange.isNotIn('z', 'x');
        assertEquals('x', range.getStart());
        assertTrue(range.isNegated());
    }

    @Test
    public void testContainsCharWhenNegatedRange() {
        CharRange range = CharRange.isNotIn('b', 'd');
        assertFalse(range.contains('c'));
        assertTrue(range.contains('a'));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContainsRangeNullThrows() {
        CharRange range = CharRange.is('a');
        range.contains((CharRange) null);
    }

    @Test
    public void testContainsRangeNonNegatedContainsNonNegated() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('b', 'y');
        assertTrue(outer.contains(inner));
        assertFalse(inner.contains(outer));
    }

    @Test
    public void testContainsRangeNonNegatedDoesNotContainDisjoint() {
        CharRange outer = CharRange.isIn('a', 'f');
        CharRange inner = CharRange.isIn('g', 'h');
        assertFalse(outer.contains(inner));
        assertTrue(inner.contains('g'));
    }

    @Test
    public void testContainsRangeNegatedContainsNonNegatedWhenDisjointLeft() {
        CharRange neg = CharRange.isNotIn('d', 'f'); // contains everything except d-f
        CharRange disjointLeft = CharRange.isIn('a', 'c');
        assertTrue(neg.contains(disjointLeft));
        assertFalse(neg.contains(CharRange.isIn('e', 'e')));
    }

    @Test
    public void testContainsRangeNegatedDoesNotContainNonNegatedWhenOverlaps() {
        CharRange neg = CharRange.isNotIn('d', 'f');
        CharRange overlap = CharRange.isIn('c', 'e');
        assertFalse(neg.contains(overlap));
        assertTrue(neg.contains('a'));
    }

    @Test
    public void testContainsRangeNegatedContainsNegatedWhenWithin() {
        CharRange big = CharRange.isNotIn('c', 'x');
        CharRange small = CharRange.isNotIn('d', 'w');
        assertTrue(big.contains(small));
        assertFalse(small.contains(big));
    }

    @Test
    public void testContainsRangeNonNegatedContainsNegatedOnlyWhenFullRange() {
        CharRange full = CharRange.isIn((char) 0, Character.MAX_VALUE);
        CharRange neg = CharRange.isNot('a');
        assertTrue(full.contains(neg));
        assertFalse(CharRange.isIn('a', 'z').contains(neg));
    }

    @Test
    public void testEqualsSameInstanceAndDifferentType() {
        CharRange range = CharRange.isIn('a', 'c');
        assertTrue(range.equals(range));
        assertFalse(range.equals("a-c"));
    }

    @Test
    public void testEqualsAndHashCodeForSameValues() {
        CharRange r1 = CharRange.isNotIn('a', 'c');
        CharRange r2 = CharRange.isNotIn('c', 'a'); // reversed inputs should normalize
        assertTrue(r1.equals(r2));
        assertEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testNotEqualsWhenNegationDiffers() {
        CharRange r1 = CharRange.is('a');
        CharRange r2 = CharRange.isNot('a');
        assertFalse(r1.equals(r2));
        assertNotEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testToStringSingleCharAndCaching() {
        CharRange range = CharRange.is('a');
        String s1 = range.toString();
        String s2 = range.toString();
        assertEquals("a", s1);
        assertSame(s1, s2);
    }

    @Test
    public void testToStringRangeAndNegated() {
        CharRange range = CharRange.isNotIn('a', 'c');
        assertEquals("^a-c", range.toString());
        assertTrue(range.toString().startsWith("^"));
    }
}

public ByteVector putUTF8(final String s) {
    int charLength = s.length();
    int len = length;
    if (len + 2 + charLength > data.length) {
        enlarge(2 + charLength);
    }
    byte[] data = this.data;
    // optimistic algorithm: instead of computing the byte length and then
    // serializing the string (which requires two loops), we assume the byte
    // length is equal to char length (which is the most frequent case), and
    // we start serializing the string right away. During the serialization,
    // if we find that this assumption is wrong, we continue with the
    // general method.
    data[len++] = (byte) (charLength >>> 8);
    data[len++] = (byte) charLength;
    for (int i = 0; i < charLength; ++i) {
        char c = s.charAt(i);
        if (c >= '\001' && c <= '\177') {
            data[len++] = (byte) c;
        } else {
            int byteLength = i;
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
                if (c >= '\001' && c <= '\177') {
                    byteLength++;
                } else if (c > '\u07FF') {
                    byteLength += 3;
                } else {
                    byteLength += 2;
                }
            }
            data[length] = (byte) (byteLength >>> 8);
            data[length + 1] = (byte) byteLength;
            if (length + 2 + byteLength > data.length) {
                length = len;
                enlarge(2 + byteLength);
                data = this.data;
            }
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
                if (c >= '\001' && c <= '\177') {
                    data[len++] = (byte) c;
                } else if (c > '\u07FF') {
                    data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                    data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                    data[len++] = (byte) (0x80 | c & 0x3F);
                } else {
                    data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                    data[len++] = (byte) (0x80 | c & 0x3F);
                }
            }
            break;
        }
    }
    length = len;
    return this;
}

