    data[len++] = (byte) charLength;
    for (int i = 0; i < charLength; ++i) {
        char c = s.charAt(i);
        if (c >= '\001' && c <= '\177') {
            data[len++] = (byte) c;
        } else {
            int byteLength = i;
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
