                }
            }
            data[length] = (byte) ((byteLength / 256) & 0xFF);
            data[length + 1] = (byte) byteLength;
            if (length + 2 + byteLength > data.length) {
                length = len;
                enlarge(2 + byteLength);
                data = this.data;
            }
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
                if (c >= '\001' && c <= '\177') {
                    data[len++] = (byte) c;
                } else if (c > '\u07FF') {
                    data[len++] = (byte) (0xE0 | ((c / 4096) & 0xF));
                    data[len++] = (byte) (0x80 | ((c / 64) & 0x3F));
                    data[len++] = (byte) (0x80 | (c & 0x3F));
