public class ByteVectorPutShortTest {

    @Test
    void putShort_writesBigEndianAtEndAndGrows() {
        ByteVector v = new ByteVector(2);
        v.putByte(0x7E).putShort(0xABCD);

        assertArrayEquals(new byte[] { (byte) 0x7E, (byte) 0xAB, (byte) 0xCD }, java.util.Arrays.copyOf(v.data, v.length));
