import java.lang.reflect.Field;
import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesAsciiAndMultiByteAndUpdatesLengthHeader() throws Exception {
        ByteVector bv = new ByteVector(4);
        bv.putByte(0x55).putUTF8("A\u0080\u0800");

        Field dataField = ByteVector.class.getDeclaredField("data");
        dataField.setAccessible(true);
        byte[] data = (byte[]) dataField.get(bv);

        assertEquals(10, bv.length);

        assertArrayEquals(
                new byte[] {
                        0x55,
                        0x00, 0x06,             // UTF8 byte length = 6
                        0x41,                   // 'A'
                        (byte) 0xC2, (byte) 0x80, // U+0080
                        (byte) 0xE0, (byte) 0xA0, (byte) 0x80 // U+0800
                },
                java.util.Arrays.copyOf(data, bv.length)
        );
    }
}

