public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesLengthAndMultiByteCharsCorrectly() {
        ByteVector bv = new ByteVector(1);
        bv.putUTF8("\u0000\u0080\u0800");

        assertEquals(9, bv.length);
        assertArrayEquals(
                new byte[] {
                        0x00, 0x07,                   // UTF8 byte length = 7
                        (byte) 0xC0, (byte) 0x80,      // U+0000 (modified UTF-8)
                        (byte) 0xC2, (byte) 0x80,      // U+0080
                        (byte) 0xE0, (byte) 0xA0, (byte) 0x80 // U+0800
                },
                java.util.Arrays.copyOf(bv.data, bv.length)
        );
    }
