import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.lang.reflect.Field;
import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_shouldWriteModifiedUtf8LengthAndBytesForMixedChars() throws Exception {
        String s = "A\u0001\u07FF\u0800Z";
        byte[] expectedBytes = new byte[] {
                0x41,
                0x01,
                (byte) 0xDF, (byte) 0xBF,
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80,
                0x5A
        };
        int expectedLength = expectedBytes.length;

        ByteVector bv = new ByteVector(2);
        bv.putUTF8(s);

        assertEquals(2 + expectedLength, bv.length);

        Field dataField = ByteVector.class.getDeclaredField("data");
        dataField.setAccessible(true);
        byte[] data = (byte[]) dataField.get(bv);

        byte[] actual = new byte[bv.length];
        System.arraycopy(data, 0, actual, 0, bv.length);

        byte[] expected = new byte[2 + expectedLength];
        expected[0] = (byte) (expectedLength >>> 8);
        expected[1] = (byte) expectedLength;
        System.arraycopy(expectedBytes, 0, expected, 2, expectedLength);

        assertArrayEquals(expected, actual);
    }
}

