import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.Test;
import java.util.Arrays;

public class ByteVectorPutByteArrayTest {

    @Test
    void putByteArray_copiesExactRange_andEnlargesAndAppendsAtCurrentLength() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(0x7F);

        byte[] src = new byte[] { 10, 20, 30, 40, 50 };
        bv.putByteArray(src, 1, 3);

        assertEquals(4, bv.length);
        assertArrayEquals(new byte[] { 0x7F, 20, 30, 40 }, Arrays.copyOf(bv.data, bv.length));
    }
}

