        byte[] src = new byte[] { 10, 11, 12, 13, 14 };
        v.putByteArray(src, 2, 3);

        assertArrayEquals(new byte[] { (byte) 0x55, 12, 13, 14 }, java.util.Arrays.copyOf(v.data, v.length));
        assertEquals(4, v.length);
    }
