import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() {
        ByteVector bv = new ByteVector();
        assertEquals(64, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector bv = new ByteVector(3);
        assertEquals(3, bv.data.length);
        assertEquals(0, bv.length);
    }

    @Test
    public void testPutByteStoresLow8BitsAndIncrementsLength() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(0x1FF);
        assertEquals(1, bv.length);
        assertEquals((byte) 0xFF, bv.data[0]);
    }

    @Test
    public void testPutByteReturnsThis() {
        ByteVector bv = new ByteVector(1);
        ByteVector ret = bv.putByte(7);
        assertSame(bv, ret);
        assertEquals(1, bv.length);
    }

    @Test
    public void testPutByteEnlargesWhenNeededAndPreservesContent() {
        ByteVector bv = new ByteVector(1);
        bv.putByte(1).putByte(2);
        assertTrue(bv.data.length >= 2);
        assertEquals((byte) 1, bv.data[0]);
    }

    @Test
    public void testPutShortBigEndianEncoding() {
        ByteVector bv = new ByteVector(4);
        bv.putShort(0x1234);
        assertEquals((byte) 0x12, bv.data[0]);
        assertEquals((byte) 0x34, bv.data[1]);
    }

    @Test
    public void testPutShortIncrementsLengthByTwo() {
        ByteVector bv = new ByteVector(2);
        bv.putShort(0x0001);
        assertEquals(2, bv.length);
        assertTrue(bv.data.length >= 2);
    }

    @Test
    public void testPutIntBigEndianEncoding() {
        ByteVector bv = new ByteVector(4);
        bv.putInt(0x01020304);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x04, bv.data[3]);
    }

    @Test
    public void testPutIntIncrementsLengthByFour() {
        ByteVector bv = new ByteVector(3);
        bv.putInt(0x0);
        assertEquals(4, bv.length);
        assertTrue(bv.data.length >= 4);
    }

    @Test
    public void testPutLongBigEndianEncodingHighAndLow() {
        ByteVector bv = new ByteVector(8);
        bv.putLong(0x0102030405060708L);
        assertEquals((byte) 0x01, bv.data[0]);
        assertEquals((byte) 0x08, bv.data[7]);
    }

    @Test
    public void testPutLongIncrementsLengthByEight() {
        ByteVector bv = new ByteVector(1);
        bv.putLong(0L);
        assertEquals(8, bv.length);
        assertTrue(bv.data.length >= 8);
    }

    @Test
    public void testPutUTF8AsciiLengthPrefixAndBytes() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("Hi");
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
    }

    @Test
    public void testPutUTF8AsciiContentAndTotalLength() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("Hi");
        assertEquals((byte) 'H', bv.data[2]);
        assertEquals(4, bv.length);
    }

    @Test
    public void testPutUTF8TwoByteCharacterEncodingAndLengthPrefix() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u0080");
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) 0x02, bv.data[1]);
    }

    @Test
    public void testPutUTF8TwoByteCharacterActualBytes() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u0080");
        assertEquals((byte) 0xC2, bv.data[2]);
        assertEquals((byte) 0x80, bv.data[3]);
    }

    @Test
    public void testPutUTF8ThreeByteCharacterEncodingAndLengthPrefix() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u0800");
        assertEquals((byte) 0x00, bv.data[0]);
        assertEquals((byte) 0x03, bv.data[1]);
    }

    @Test
    public void testPutUTF8ThreeByteCharacterActualBytes() {
        ByteVector bv = new ByteVector(10);
        bv.putUTF8("\u0800");
        assertEquals((byte) 0xE0, bv.data[2]);
        assertEquals((byte) 0x80, bv.data[3]);
    }

    @Test
    public void testPutUTF8EnlargesWhenNonAsciiRequiresMoreBytes() {
        ByteVector bv = new ByteVector(3);
        bv.putUTF8("\u0080");
        assertTrue(bv.data.length >= 4);
        assertEquals(4, bv.length);
    }

    @Test
    public void testPutByteArrayCopiesRangeCorrectly() {
        ByteVector bv = new ByteVector(10);
        byte[] src = new byte[] { 9, 8, 7, 6 };
        bv.putByteArray(src, 1, 2);
        assertEquals((byte) 8, bv.data[0]);
        assertEquals((byte) 7, bv.data[1]);
    }

    @Test
    public void testPutByteArrayNullWritesZerosAndIncrementsLength() {
        ByteVector bv = new ByteVector(4);
        bv.putByteArray(null, 0, 2);
        assertEquals(2, bv.length);
        assertEquals((byte) 0, bv.data[1]);
    }

    @Test
    public void testPutByteArrayEnlargesAndPreservesExistingBytes() {
        ByteVector bv = new ByteVector(2);
        bv.putByte(1).putByte(2);
        bv.putByteArray(new byte[] { 3, 4, 5 }, 0, 3);
        assertTrue(bv.data.length >= 5);
        assertEquals((byte) 2, bv.data[1]);
    }

    @Test
    public void testPackagePrivatePut11WritesTwoBytes() {
        ByteVector bv = new ByteVector(2);
        bv.put11(0x11, 0x22);
        assertEquals((byte) 0x11, bv.data[0]);
        assertEquals((byte) 0x22, bv.data[1]);
    }

    @Test
    public void testPackagePrivatePut12WritesByteThenShort() {
        ByteVector bv = new ByteVector(3);
        bv.put12(0x7F, 0x1234);
        assertEquals((byte) 0x7F, bv.data[0]);
        assertEquals((byte) 0x12, bv.data[1]);
    }
}
