import org.junit.Test;

import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterRangeBasics() {
        CharRange r = CharRange.is('a');
        assertEquals('a', r.getStart());
        assertEquals('a', r.getEnd());
    }

    @Test
    public void testIsSingleCharacterRangeNegatedFlag() {
        CharRange r = CharRange.is('a');
        assertFalse(r.isNegated());
        assertTrue(r.contains('a'));
    }

    @Test
    public void testIsNotSingleCharacterRangeBasics() {
        CharRange r = CharRange.isNot('a');
        assertEquals('a', r.getStart());
        assertEquals('a', r.getEnd());
    }

    @Test
    public void testIsNotSingleCharacterRangeNegatedContains() {
        CharRange r = CharRange.isNot('a');
        assertTrue(r.isNegated());
        assertFalse(r.contains('a'));
    }

    @Test
    public void testIsInReversesWrongOrder() {
        CharRange r = CharRange.isIn('e', 'a');
        assertEquals('a', r.getStart());
        assertEquals('e', r.getEnd());
    }

    @Test
    public void testIsInContainsBoundaries() {
        CharRange r = CharRange.isIn('a', 'e');
        assertTrue(r.contains('a'));
        assertTrue(r.contains('e'));
    }

    @Test
    public void testIsInDoesNotContainOutside() {
        CharRange r = CharRange.isIn('a', 'e');
        assertFalse(r.contains('`'));
        assertFalse(r.contains('f'));
    }

    @Test
    public void testIsNotInReversesWrongOrder() {
        CharRange r = CharRange.isNotIn('z', 'x');
        assertEquals('x', r.getStart());
        assertEquals('z', r.getEnd());
    }

    @Test
    public void testIsNotInContainsOutsideAndExcludesInside() {
        CharRange r = CharRange.isNotIn('a', 'c');
        assertTrue(r.contains('z'));
        assertFalse(r.contains('b'));
    }

    @Test(expected = IllegalArgumentException.class)
    public void testContainsRangeRejectsNull() {
        CharRange.is('a').contains((CharRange) null);
    }

    @Test
    public void testContainsRangeNonNegatedContainsNonNegated() {
        CharRange outer = CharRange.isIn('a', 'e');
        CharRange inner = CharRange.isIn('b', 'd');
        assertTrue(outer.contains(inner));
        assertFalse(inner.contains(outer));
    }

    @Test
    public void testContainsRangeNonNegatedContainsNegatedOnlyWhenFullDomain() {
        CharRange notB = CharRange.isNot('b');
        CharRange full = CharRange.isIn((char) 0, Character.MAX_VALUE);
        assertTrue(full.contains(notB));
        assertFalse(CharRange.isIn('a', 'z').contains(notB));
    }

    @Test
    public void testContainsRangeNegatedContainsNonNegatedDisjoint() {
        CharRange negated = CharRange.isNotIn('c', 'm');
        CharRange disjointBelow = CharRange.isIn('a', 'b');
        assertTrue(negated.contains(disjointBelow));
        assertFalse(negated.contains(CharRange.isIn('d', 'e')));
    }

    @Test
    public void testContainsRangeNegatedContainsNegatedWhenSupersetExclusion() {
        CharRange aToZNot = CharRange.isNotIn('a', 'z');
        CharRange cToMNot = CharRange.isNotIn('c', 'm');
        assertTrue(cToMNot.contains(aToZNot));
        assertFalse(aToZNot.contains(cToMNot));
    }

    @Test
    public void testEqualsAndHashCodeSameForSameDefinition() {
        CharRange r1 = CharRange.isNotIn('a', 'c');
        CharRange r2 = CharRange.isNotIn('c', 'a');
        assertEquals(r1, r2);
        assertEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testEqualsDifferentNegationNotEqual() {
        CharRange r1 = CharRange.isIn('a', 'c');
        CharRange r2 = CharRange.isNotIn('a', 'c');
        assertNotEquals(r1, r2);
        assertNotEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testEqualsSameInstanceAndNotCharRange() {
        CharRange r = CharRange.isIn('a', 'c');
        assertTrue(r.equals(r));
        assertFalse(r.equals("a-c"));
    }

    @Test
    public void testToStringSingleAndNegatedSingle() {
        assertEquals("a", CharRange.is('a').toString());
        assertEquals("^a", CharRange.isNot('a').toString());
    }

    @Test
    public void testToStringRangeAndNegatedRange() {
        assertEquals("a-e", CharRange.isIn('a', 'e').toString());
        assertEquals("^a-e", CharRange.isNotIn('a', 'e').toString());
    }

    @Test
    public void testToStringCachesAndReturnsSameContent() {
        CharRange r = CharRange.isNotIn('a', 'e');
        String s1 = r.toString();
        String s2 = r.toString();
        assertSame(s1, s2);
    }
}
