public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedAsciiAndNonAsciiAndUpdatesLengthAndPrefix() {
        ByteVector bv = new ByteVector(2);
        String s = "A\u07FF\u0800B";

        bv.putUTF8(s);

