import org.junit.jupiter.api.Test;

public class CharRangeToStringTest {

    @Test
    void toString_negatedReordersAndCaches() {
        CharRange range = CharRange.isNotIn('z', 'a'); // should reorder to a-z and be negated => ^a-z

        String first = range.toString();
        String second = range.toString();

        assertEquals("^a-z", first);
        assertSame(first, second);
    }
}

