public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesLengthAndBytes_forMixed1_2_3ByteChars_andEnlarges() {
        ByteVector bv = new ByteVector(2);
        bv.putUTF8("A\u0000\u0080\u0800");

        assertEquals(10, bv.length);

        assertArrayEquals(
                new byte[] {
                        0x00, 0x09,                   // UTF-8 byte length = 9
                        0x41,                         // 'A'
                        (byte) 0xC0, (byte) 0x80,      // U+0000
