import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testReversedEndpointsAffectContainsAndToString() {
        CharRange r = CharRange.isNotIn('z', 'a'); // will normalize to a-z, negated
        assertEquals("^a-z", r.toString());
        assertFalse(r.contains('m'));
    }
