        bv.put12(0xAB, 0x1234);

        assertEquals(3, bv.length);
        assertArrayEquals(new byte[] { (byte) 0xAB, 0x12, 0x34 }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
