public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedAsciiAndMultiByteAndWritesCorrectLength() {
        ByteVector bv = new ByteVector(2); // force resize path
        String s = "A\u0080\u0800"; // 1-byte, 2-byte, 3-byte => total 6 bytes

        bv.putUTF8(s);

        byte[] actual = Arrays.copyOf(bv.data, bv.length);
        byte[] expected = new byte[] {
                0x00, 0x06,
                0x41,
                (byte) 0xC2, (byte) 0x80,
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80
        };
        assertArrayEquals(expected, actual);
    }
