import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedCharsWithCorrectModifiedUtf8LengthAndBytes() {
        String s = "A" + "\u0000" + "\u07FF" + "\u0800" + "B";
        ByteVector bv = new ByteVector(1);
        bv.putUTF8(s);

        byte[] modified = new byte[] {
                0x41,
                (byte) 0xC0, (byte) 0x80,
                (byte) 0xDF, (byte) 0xBF,
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80,
                0x42
        };

        byte[] expected = new byte[2 + modified.length];
        expected[0] = (byte) (modified.length >>> 8);
        expected[1] = (byte) modified.length;
        System.arraycopy(modified, 0, expected, 2, modified.length);

        assertEquals(expected.length, bv.length);
        assertArrayEquals(expected, java.util.Arrays.copyOf(bv.data, bv.length));
    }
}

