import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedCharsAndUpdatesLengthHeader() throws Exception {
        ByteVector bv = new ByteVector(4); // force enlarge paths
        String s = "A\u0000\u0800"; // ASCII + 2-byte UTF8 + 3-byte UTF8 => 1 + 2 + 3 = 6 bytes

        bv.putUTF8(s);

        byte[] out = new byte[bv.length];
        System.arraycopy(bv.data, 0, out, 0, bv.length);

        assertArrayEquals(new byte[] {
                0x00, 0x06,             // modified UTF8 byte length
                0x41,                   // 'A'
                (byte) 0xC0, (byte) 0x80, // U+0000
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80 // U+0800
        }, out);
        assertEquals(8, bv.length);
    }
}

