import org.junit.jupiter.api.Test;

public class ByteVectorPut12Test {

    @Test
    void put12_writesByteThenShortBigEndian_andUpdatesLength_evenWhenEnlarging() {
        ByteVector bv = new ByteVector(2); // force enlarge on put12
        bv.put12(0xAB, 0xCDEF);

        assertArrayEquals(new byte[] { (byte) 0xAB, (byte) 0xCD, (byte) 0xEF }, new byte[] { bv.data[0], bv.data[1], bv.data[2] });
        assertEquals(3, bv.length);
    }
}

