import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testReversedNegatedContainsAndToString() {
        CharRange r = CharRange.isNotIn('z', 'a'); // constructor should reorder to a-z, negated
        assertEquals("^a-z", r.toString());
        assertFalse(r.contains('m'));
    }
