/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() {
        ByteVector v = new ByteVector();
        assertEquals(0, v.length);
        assertEquals(64, v.data.length);
    }

    @Test
    public void testInitialSizeConstructor() {
        ByteVector v = new ByteVector(3);
        assertEquals(0, v.length);
        assertEquals(3, v.data.length);
    }

    @Test
    public void testPutByteStoresValueAndUpdatesLength() {
        ByteVector v = new ByteVector(1);
        v.putByte(0xAB);
        assertEquals(1, v.length);
        assertEquals((byte) 0xAB, v.data[0]);
    }

    @Test
    public void testPutByteEnlargesWhenFull() {
        ByteVector v = new ByteVector(1);
        v.putByte(1).putByte(2);
        assertEquals(2, v.length);
        assertTrue(v.data.length >= 2);
    }

    @Test
    public void testPut11WritesTwoBytes() {
        ByteVector v = new ByteVector(2);
        v.put11(0x01, 0xFE);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0x01, (byte) 0xFE }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPut11Enlarges() {
        ByteVector v = new ByteVector(1);
        v.put11(7, 8);
        assertEquals(2, v.length);
        assertTrue(v.data.length >= 2);
    }

    @Test
    public void testPutShortBigEndian() {
        ByteVector v = new ByteVector(2);
        v.putShort(0x1234);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 0x12, 0x34 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPutShortEnlarges() {
        ByteVector v = new ByteVector(1);
        v.putShort(0x0102);
        assertEquals(2, v.length);
        assertTrue(v.data.length >= 2);
    }

    @Test
    public void testPut12WritesByteThenShort() {
        ByteVector v = new ByteVector(3);
        v.put12(0x7F, 0x0203);
        assertEquals(3, v.length);
        assertArrayEquals(new byte[] { 0x7F, 0x02, 0x03 }, new byte[] { v.data[0], v.data[1], v.data[2] });
    }

    @Test
    public void testPut12Enlarges() {
        ByteVector v = new ByteVector(2);
        v.put12(1, 0x0203);
        assertEquals(3, v.length);
        assertTrue(v.data.length >= 3);
    }

    @Test
    public void testPutIntBigEndian() {
        ByteVector v = new ByteVector(4);
        v.putInt(0x01020304);
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutIntEnlarges() {
        ByteVector v = new ByteVector(3);
        v.putInt(0x0A0B0C0D);
        assertEquals(4, v.length);
        assertTrue(v.data.length >= 4);
    }

    @Test
    public void testPutLongBigEndian() {
        ByteVector v = new ByteVector(8);
        v.putLong(0x0102030405060708L);
        assertEquals(8, v.length);
        assertArrayEquals(new byte[] { 0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4], v.data[5], v.data[6], v.data[7] });
    }

    @Test
    public void testPutLongEnlarges() {
        ByteVector v = new ByteVector(7);
        v.putLong(0x1112131415161718L);
        assertEquals(8, v.length);
        assertTrue(v.data.length >= 8);
    }

    @Test
    public void testPutUTF8AsciiOnlyWritesLengthAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("AB");
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, 0x41, 0x42 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutUTF8TwoByteCharEncoding() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u00A2"); // CENT SIGN, 2-byte UTF-8: C2 A2
        assertEquals(4, v.length);
        assertArrayEquals(new byte[] { 0x00, 0x02, (byte) 0xC2, (byte) 0xA2 },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3] });
    }

    @Test
    public void testPutUTF8ThreeByteCharEncoding() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u20AC"); // EURO SIGN, 3-byte UTF-8: E2 82 AC
        assertEquals(5, v.length);
        assertArrayEquals(new byte[] { 0x00, 0x03, (byte) 0xE2, (byte) 0x82, (byte) 0xAC },
                new byte[] { v.data[0], v.data[1], v.data[2], v.data[3], v.data[4] });
    }

    @Test
    public void testPutUTF8MixedCharsUpdatesLengthFieldToByteLength() {
        ByteVector v = new ByteVector(20);
        v.putUTF8("A\u00A2\u20AC"); // bytes: 1 + 2 + 3 = 6
        assertEquals(8, v.length);
        assertEquals(6, ((v.data[0] & 0xFF) << 8) | (v.data[1] & 0xFF));
    }

    @Test
    public void testPutUTF8EnlargesWhenNecessary() {
        ByteVector v = new ByteVector(3);
        v.putUTF8("AB");
        assertEquals(4, v.length);
        assertTrue(v.data.length >= 4);
    }

    @Test
    public void testPutByteArrayCopiesBytes() {
        ByteVector v = new ByteVector(5);
        byte[] src = new byte[] { 9, 8, 7, 6 };
        v.putByteArray(src, 1, 2);
        assertEquals(2, v.length);
        assertArrayEquals(new byte[] { 8, 7 }, new byte[] { v.data[0], v.data[1] });
    }

    @Test
    public void testPutByteArrayWithNullWritesZerosAndAdvancesLength() {
        ByteVector v = new ByteVector(4);
        v.putByteArray(null, 0, 3);
        assertEquals(3, v.length);
        assertArrayEquals(new byte[] { 0, 0, 0 }, new byte[] { v.data[0], v.data[1], v.data[2] });
    }

    @Test
    public void testPutByteArrayEnlargesAndPreservesExistingContent() {
        ByteVector v = new ByteVector(2);
        v.putByte(1).putByte(2);
        v.putByteArray(new byte[] { 3, 4, 5 }, 0, 3);
        assertEquals(5, v.length);
        assertEquals(2, v.data[1]);
    }
}

/**
 * <p>A contiguous range of characters, optionally negated.</p>
 * 
 * <p>Instances are immutable.</p>
 */
public class CharRange {

    /** The first character, inclusive, in the range. */
    private final char start;
    /** The last character, inclusive, in the range. */
    private final char end;
    /** True if the range is everything except the characters specified. */
    private final boolean negated;

    /** Cached toString. */
    private transient String iToString;

    /**
     * <p>Constructs a {@code CharRange} over a set of characters,
     * optionally negating the range.</p>
     *
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     * 
     * <p>If start and end are in the wrong order, they are reversed.
     * Thus {@code a-e} is the same as {@code e-a}.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @param negated  true to express everything except the range
     */
    private CharRange(char start, char end, final boolean negated) {
        super();
        if (start > end) {
            final char temp = start;
            start = end;
            end = temp;
        }

        this.start = start;
        this.end = end;
        this.negated = negated;
    }

    /**
     * <p>Constructs a {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange is(final char ch) {
        return new CharRange(ch, ch, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a single character.</p>
     *
     * @param ch  only character in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNot(final char ch) {
        return new CharRange(ch, ch, true);
    }

    /**
     * <p>Constructs a {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isIn(final char start, final char end) {
        return new CharRange(start, end, false);
    }

    /**
     * <p>Constructs a negated {@code CharRange} over a set of characters.</p>
     *
     * @param start  first character, inclusive, in this range
     * @param end  last character, inclusive, in this range
     * @return the new CharRange object
     * @see CharRange#CharRange(char, char, boolean)
     * @since 2.5
     */
    public static CharRange isNotIn(final char start, final char end) {
        return new CharRange(start, end, true);
    }

    // Accessors
    //-----------------------------------------------------------------------
    /**
     * <p>Gets the start character for this character range.</p>
     * 
     * @return the start char (inclusive)
     */
    public char getStart() {
        return this.start;
    }

    /**
     * <p>Gets the end character for this character range.</p>
     * 
     * @return the end char (inclusive)
     */
    public char getEnd() {
        return this.end;
    }

    /**
     * <p>Is this {@code CharRange} negated.</p>
     * 
     * <p>A negated range includes everything except that defined by the
     * start and end characters.</p>
     *
     * @return {@code true} if negated
     */
    public boolean isNegated() {
        return negated;
    }

    // Contains
    //-----------------------------------------------------------------------
    /**
     * <p>Is the character specified contained in this range.</p>
     *
     * @param ch  the character to check
     * @return {@code true} if this range contains the input character
     */
    public boolean contains(final char ch) {
        return (ch >= start && ch <= end) != negated;
    }

    /**
     * <p>Are all the characters of the passed in range contained in
     * this range.</p>
     *
     * @param range  the range to check against
     * @return {@code true} if this range entirely contains the input range
     * @throws IllegalArgumentException if {@code null} input
     */
    public boolean contains(final CharRange range) {
        if (range == null) {
            throw new IllegalArgumentException("The Range must not be null");
        }
        if (negated) {
            if (range.negated) {
                return start >= range.start && end <= range.end;
            }
            return range.end < start || range.start > end;
        }
        if (range.negated) {
            return start == 0 && end == Character.MAX_VALUE;
        }
        return start <= range.start && end >= range.end;
    }

    // Basics
    //-----------------------------------------------------------------------
    /**
     * <p>Compares two CharRange objects, returning true if they represent
     * exactly the same range of characters defined in the same way.</p>
     * 
     * @param obj  the object to compare to
     * @return true if equal
     */
    @Override
    public boolean equals(final Object obj) {
        if (obj == this) {
            return true;
        }
        if (obj instanceof CharRange == false) {
            return false;
        }
        final CharRange other = (CharRange) obj;
        return start == other.start && end == other.end && negated == other.negated;
    }

    /**
     * <p>Gets a hashCode compatible with the equals method.</p>
     * 
     * @return a suitable hashCode
     */
    @Override
    public int hashCode() {
        return 83 + start + 7 * end + (negated ? 1 : 0);
    }

    /**
     * <p>Gets a string representation of the character range.</p>
     * 
     * @return string representation of this range
     */
    @Override
    public String toString() {
        if (iToString == null) {
            final StringBuilder buf = new StringBuilder(4);
            if (isNegated()) {
                buf.append('^');
            }
            buf.append(start);
            if (start != end) {
                buf.append('-');
                buf.append(end);
            }
            iToString = buf.toString();
        }
        return iToString;
    }

}

import org.junit.Test;
import static org.junit.Assert.*;

public class CharRangeTest {

    @Test
    public void testIsSingleCharacterAccessorsAndNotNegated() {
        CharRange r = CharRange.is('a');
        assertEquals('a', r.getStart());
        assertFalse(r.isNegated());
    }

    @Test
    public void testIsSingleCharacterEndAndContains() {
        CharRange r = CharRange.is('a');
        assertEquals('a', r.getEnd());
        assertTrue(r.contains('a'));
    }

    @Test
    public void testIsNotSingleCharacterNegatedAndContainsOther() {
        CharRange r = CharRange.isNot('a');
        assertTrue(r.isNegated());
        assertTrue(r.contains('b'));
    }

    @Test
    public void testIsNotSingleCharacterDoesNotContainSelfAndToString() {
        CharRange r = CharRange.isNot('a');
        assertFalse(r.contains('a'));
        assertEquals("^a", r.toString());
    }

    @Test
    public void testIsInOrdersRangeWhenReversed() {
        CharRange r = CharRange.isIn('e', 'a');
        assertEquals('a', r.getStart());
        assertEquals('e', r.getEnd());
    }

    @Test
    public void testIsInContainsBounds() {
        CharRange r = CharRange.isIn('a', 'e');
        assertTrue(r.contains('a'));
        assertTrue(r.contains('e'));
    }

    @Test
    public void testIsInDoesNotContainOutside() {
        CharRange r = CharRange.isIn('a', 'e');
        assertFalse(r.contains('`'));
        assertFalse(r.contains('f'));
    }

    @Test
    public void testIsNotInNegatedAndContainsInsideIsFalse() {
        CharRange r = CharRange.isNotIn('a', 'e');
        assertTrue(r.isNegated());
        assertFalse(r.contains('c'));
    }

    @Test
    public void testIsNotInContainsOutsideIsTrueAndToString() {
        CharRange r = CharRange.isNotIn('a', 'e');
        assertTrue(r.contains('f'));
        assertEquals("^a-e", r.toString());
    }

    @Test
    public void testContainsRangeThrowsOnNull() {
        CharRange r = CharRange.isIn('a', 'z');
        try {
            r.contains((CharRange) null);
            fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException ex) {
            assertEquals("The Range must not be null", ex.getMessage());
        }
    }

    @Test
    public void testContainsRangeNonNegatedContainsNonNegatedTrue() {
        CharRange outer = CharRange.isIn('a', 'z');
        CharRange inner = CharRange.isIn('c', 'd');
        assertTrue(outer.contains(inner));
        assertFalse(inner.contains(outer));
    }

    @Test
    public void testContainsRangeNonNegatedDoesNotContainNonNegatedFalse() {
        CharRange outer = CharRange.isIn('a', 'd');
        CharRange inner = CharRange.isIn('c', 'f');
        assertFalse(outer.contains(inner));
        assertTrue(inner.contains(CharRange.isIn('c', 'd')));
    }

    @Test
    public void testContainsRangeNegatedContainsNonNegatedOutsideTrue() {
        CharRange neg = CharRange.isNotIn('d', 'f');
        CharRange outside = CharRange.isIn('a', 'c');
        assertTrue(neg.contains(outside));
        assertFalse(neg.contains(CharRange.isIn('e', 'e')));
    }

    @Test
    public void testContainsRangeNegatedDoesNotContainNonNegatedOverlappingFalse() {
        CharRange neg = CharRange.isNotIn('d', 'f');
        CharRange overlapping = CharRange.isIn('c', 'e');
        assertFalse(neg.contains(overlapping));
        assertFalse(neg.contains(CharRange.isIn('f', 'g')));
    }

    @Test
    public void testContainsRangeNegatedContainsNegatedWhenMoreRestrictive() {
        CharRange negSmallExcluded = CharRange.isNotIn('d', 'f'); // allows more chars
        CharRange negBigExcluded = CharRange.isNotIn('b', 'h');   // allows fewer chars
        assertFalse(negSmallExcluded.contains(negBigExcluded));
        assertTrue(negBigExcluded.contains(negSmallExcluded));
    }

    @Test
    public void testContainsRangeNonNegatedContainsNegatedOnlyWhenFullUniverse() {
        CharRange all = CharRange.isIn((char) 0, Character.MAX_VALUE);
        CharRange neg = CharRange.isNotIn('a', 'z');
        assertTrue(all.contains(neg));
        assertFalse(CharRange.isIn('a', 'z').contains(neg));
    }

    @Test
    public void testEqualsSameInstanceAndDifferentType() {
        CharRange r = CharRange.isIn('a', 'b');
        assertTrue(r.equals(r));
        assertFalse(r.equals("not a range"));
    }

    @Test
    public void testEqualsSameValuesAndHashCodeSame() {
        CharRange r1 = CharRange.isNotIn('a', 'e');
        CharRange r2 = CharRange.isNotIn('a', 'e');
        assertTrue(r1.equals(r2));
        assertEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testEqualsDifferentNegationNotEqual() {
        CharRange r1 = CharRange.isIn('a', 'e');
        CharRange r2 = CharRange.isNotIn('a', 'e');
        assertFalse(r1.equals(r2));
        assertNotEquals(r1.hashCode(), r2.hashCode());
    }

    @Test
    public void testToStringSingleCharacterNoDashAndCached() {
        CharRange r = CharRange.is('x');
        String s1 = r.toString();
        String s2 = r.toString();
        assertEquals("x", s1);
        assertSame(s1, s2);
    }

    @Test
    public void testToStringRangeIncludesDashAndCached() {
        CharRange r = CharRange.isIn('a', 'c');
        String s1 = r.toString();
        String s2 = r.toString();
        assertEquals("a-c", s1);
        assertSame(s1, s2);
    }

    @Test
    public void testHashCodeFormulaNonNegated() {
        CharRange r = CharRange.isIn('a', 'c');
        int expected = 83 + 'a' + 7 * 'c' + 0;
        assertEquals(expected, r.hashCode());
        assertTrue(r.equals(CharRange.isIn('a', 'c')));
    }

    @Test
    public void testHashCodeFormulaNegated() {
        CharRange r = CharRange.isNotIn('a', 'c');
        int expected = 83 + 'a' + 7 * 'c' + 1;
        assertEquals(expected, r.hashCode());
        assertTrue(r.equals(CharRange.isNotIn('a', 'c')));
    }
}

/**
 * A dynamically extensible vector of bytes. This class is roughly equivalent to
 * a DataOutputStream on top of a ByteArrayOutputStream, but is more efficient.
 *
 */
public class ByteVector {

    /**
     * The content of this vector.
     */
    byte[] data;

    /**
     * Actual number of bytes in this vector.
     */
    int length;

    /**
     * Constructs a new ByteVector with a default initial
     * size.
     */
    public ByteVector() {
        data = new byte[64];
    }

    /**
     * Constructs a new ByteVector with the given initial
     * size.
     * 
     * @param initialSize the initial size of the byte vector to be constructed.
     */
    public ByteVector(final int initialSize) {
        data = new byte[initialSize];
    }

    /**
     * Puts a byte into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b a byte.
     * @return this byte vector.
     */
    public ByteVector putByte(final int b) {
        int length = this.length;
        if (length + 1 > data.length) {
            enlarge(1);
        }
        data[length++] = (byte) b;
        this.length = length;
        return this;
    }

    /**
     * Puts two bytes into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param b1 a byte.
     * @param b2 another byte.
     * @return this byte vector.
     */
    ByteVector put11(final int b1, final int b2) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) b1;
        data[length++] = (byte) b2;
        this.length = length;
        return this;
    }

    /**
     * Puts a short into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param s a short.
     * @return this byte vector.
     */
    public ByteVector putShort(final int s) {
        int length = this.length;
        if (length + 2 > data.length) {
            enlarge(2);
        }
        byte[] data = this.data;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts a byte and a short into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b a byte.
     * @param s a short.
     * @return this byte vector.
     */
    ByteVector put12(final int b, final int s) {
        int length = this.length;
        if (length + 3 > data.length) {
            enlarge(3);
        }
        byte[] data = this.data;
        data[length++] = (byte) b;
        data[length++] = (byte) (s >>> 8);
        data[length++] = (byte) s;
        this.length = length;
        return this;
    }

    /**
     * Puts an int into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param i an int.
     * @return this byte vector.
     */
    public ByteVector putInt(final int i) {
        int length = this.length;
        if (length + 4 > data.length) {
            enlarge(4);
        }
        byte[] data = this.data;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts a long into this byte vector. The byte vector is automatically
     * enlarged if necessary.
     * 
     * @param l a long.
     * @return this byte vector.
     */
    public ByteVector putLong(final long l) {
        int length = this.length;
        if (length + 8 > data.length) {
            enlarge(8);
        }
        byte[] data = this.data;
        int i = (int) (l >>> 32);
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        i = (int) l;
        data[length++] = (byte) (i >>> 24);
        data[length++] = (byte) (i >>> 16);
        data[length++] = (byte) (i >>> 8);
        data[length++] = (byte) i;
        this.length = length;
        return this;
    }

    /**
     * Puts an UTF8 string into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param s a String.
     * @return this byte vector.
     */
    public ByteVector putUTF8(final String s) {
        int charLength = s.length();
        int len = length;
        if (len + 2 + charLength > data.length) {
            enlarge(2 + charLength);
        }
        byte[] data = this.data;
        // optimistic algorithm: instead of computing the byte length and then
        // serializing the string (which requires two loops), we assume the byte
        // length is equal to char length (which is the most frequent case), and
        // we start serializing the string right away. During the serialization,
        // if we find that this assumption is wrong, we continue with the
        // general method.
        data[len++] = (byte) (charLength >>> 8);
        data[len++] = (byte) charLength;
        for (int i = 0; i < charLength; ++i) {
            char c = s.charAt(i);
            if (c >= '\001' && c <= '\177') {
                data[len++] = (byte) c;
            } else {
                int byteLength = i;
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        byteLength++;
                    } else if (c > '\u07FF') {
                        byteLength += 3;
                    } else {
                        byteLength += 2;
                    }
                }
                data[length] = (byte) (byteLength >>> 8);
                data[length + 1] = (byte) byteLength;
                if (length + 2 + byteLength > data.length) {
                    length = len;
                    enlarge(2 + byteLength);
                    data = this.data;
                }
                for (int j = i; j < charLength; ++j) {
                    c = s.charAt(j);
                    if (c >= '\001' && c <= '\177') {
                        data[len++] = (byte) c;
                    } else if (c > '\u07FF') {
                        data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                        data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    } else {
                        data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                        data[len++] = (byte) (0x80 | c & 0x3F);
                    }
                }
                break;
            }
        }
        length = len;
        return this;
    }

    /**
     * Puts an array of bytes into this byte vector. The byte vector is
     * automatically enlarged if necessary.
     * 
     * @param b an array of bytes. May be null to put len
     *        null bytes into this byte vector.
     * @param off index of the fist byte of b that must be copied.
     * @param len number of bytes of b that must be copied.
     * @return this byte vector.
     */
    public ByteVector putByteArray(final byte[] b, final int off, final int len)
    {
        if (length + len > data.length) {
            enlarge(len);
        }
        if (b != null) {
            System.arraycopy(b, off, data, length, len);
        }
        length += len;
        return this;
    }

    /**
     * Enlarge this byte vector so that it can receive n more bytes.
     * 
     * @param size number of additional bytes that this byte vector should be
     *        able to receive.
     */
    private void enlarge(final int size) {
        int length1 = 2 * data.length;
        int length2 = length + size;
        byte[] newData = new byte[length1 > length2 ? length1 : length2];
        System.arraycopy(data, 0, newData, 0, length);
        data = newData;
    }
}

