import org.junit.Test;

import java.lang.reflect.Field;
import java.util.Arrays;

import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() throws Exception {
        ByteVector bv = new ByteVector();

        Field dataF = ByteVector.class.getDeclaredField("data");
        dataF.setAccessible(true);
        byte[] data = (byte[]) dataF.get(bv);

        Field lenF = ByteVector.class.getDeclaredField("length");
        lenF.setAccessible(true);
        int len = (int) lenF.get(bv);

        assertEquals(64, data.length);
        assertEquals(0, len);
    }

    @Test
    public void testConstructorWithInitialSize() throws Exception {
        ByteVector bv = new ByteVector(3);

        Field dataF = ByteVector.class.getDeclaredField("data");
        dataF.setAccessible(true);
        byte[] data = (byte[]) dataF.get(bv);

        Field lenF = ByteVector.class.getDeclaredField("length");
        lenF.setAccessible(true);
        int len = (int) lenF.get(bv);

        assertEquals(3, data.length);
        assertEquals(0, len);
    }

    @Test
    public void testPutByteWritesAndReturnsThis() throws Exception {
        ByteVector bv = new ByteVector(1);
        ByteVector ret = bv.putByte(0xAB);

        Field dataF = ByteVector.class.getDeclaredField("data");
        dataF.setAccessible(true);
        byte[] data = (byte[]) dataF.get(bv);

        assertSame(bv, ret);
        assertEquals((byte) 0xAB, data[0]);
    }

    @Test
    public void testPutByteUpdatesLengthAndEnlarges() throws Exception {
        ByteVector bv = new ByteVector(1);

        Field dataF = ByteVector.class.getDeclaredField("data");
        dataF.setAccessible(true);
        byte[] before = (byte[]) dataF.get(bv);

        bv.putByte(1).putByte(2);

        byte[] after = (byte[]) dataF.get(bv);

        Field lenF = ByteVector.class.getDeclaredField("length");
        lenF.setAccessible(true);
        int len = (int) lenF.get(bv);

        assertTrue(after.length > before.length);
        assertEquals(2, len);
    }

    @Test
    public void testPut11WritesTwoBytesInOrder() throws Exception {
        ByteVector bv = new ByteVector(2);
