public ByteVector putByte(final int b) {
    int length = this.length;
    if (length + 1 > data.length) {
        enlarge(1);
    }
    data[length++] = (byte) b;
    this.length = length;
    return this;
}

public ByteVector putByte(final int b) {
    int length = this.length;
    enlarge(length + 1 - data.length);
    data[length++] = (byte) b;
    this.length = length;
    return this;
}

