    void putUTF8_encodesAsciiThenTwoByteThenThreeByteAndUpdatesLengthPrefix() {
        ByteVector bv = new ByteVector(4); // force enlarge paths
        bv.putUTF8("A\u00A2\u0800"); // 'A' (1), '¢' (2), '\u0800' (3) => 6 bytes

        assertArrayEquals(
