public class ByteVectorPutIntTest {

    @Test
    void putIntWritesBigEndianAndAdvancesLengthWithEnlargePath() {
        ByteVector bv = new ByteVector(3); // force enlarge when writing 4 bytes
        bv.putInt(0x80FF0102); // includes negative high byte and mixed bytes

        assertArrayEquals(new byte[] { (byte) 0x80, (byte) 0xFF, 0x01, 0x02 }, bv.data);
        assertEquals(4, bv.length);
    }
}

