public class ByteVectorPut12Test {

    @Test
    void put12_writesBigEndianShortAndByte_andEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(2);
        bv.put12(0xAB, 0xCDEF);

        assertArrayEquals(new byte[] { (byte) 0xAB, (byte) 0xCD, (byte) 0xEF },
