import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.util.Arrays;
import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesMixedUtf8AndUpdatesLengthHeaderAndTriggersEnlarge() {
        ByteVector bv = new ByteVector(3); // force enlarge path
        String s = "A\u0000\u0080\u0800"; // 1-byte, 2-byte, 2-byte, 3-byte => 8 bytes total
        bv.putUTF8(s);

        assertEquals(10, bv.length); // 2 (length header) + 8 (utf8 bytes)

        byte[] expected = new byte[] {
                0x00, 0x08,
                0x41,
                (byte) 0xC0, (byte) 0x80,
                (byte) 0xC2, (byte) 0x80,
                (byte) 0xE0, (byte) 0xA0, (byte) 0x80
        };
        assertArrayEquals(expected, Arrays.copyOf(bv.data, bv.length));
    }
}

