public class ByteVectorPut12Test {

    @Test
    void put12_writesByteThenShortBigEndian_andEnlargesWhenNeeded() {
        ByteVector bv = new ByteVector(2); // force enlarge for 3 bytes
        bv.put12(0xAB, 0xCDEF);

        assertArrayEquals(new byte[] { (byte) 0xAB, (byte) 0xCD, (byte) 0xEF }, java.util.Arrays.copyOf(bv.data, bv.length));
        assertEquals(3, bv.length);
    }
