import java.nio.charset.StandardCharsets;

import org.junit.jupiter.api.Test;

public class ByteVectorPutUTF8Test {

    @Test
    void putUTF8_encodesLengthAndBytes_forMixedAsciiAndTwoByteChars() {
        ByteVector bv = new ByteVector(2); // force enlarge path
        String s = "A\u0100B"; // 'A' (1 byte) + U+0100 (2 bytes) + 'B' (1 byte) => 4 bytes

        bv.putUTF8(s);

        byte[] expectedUtf8 = s.getBytes(StandardCharsets.UTF_8);
        byte[] expected = new byte[2 + expectedUtf8.length];
        expected[0] = 0;
        expected[1] = (byte) expectedUtf8.length;
        System.arraycopy(expectedUtf8, 0, expected, 2, expectedUtf8.length);

        assertEquals(expected.length, bv.length);
        assertArrayEquals(expected, java.util.Arrays.copyOf(bv.data, bv.length));
    }
}

