public class CharRangeContainsRangeTest {

    @Test
    public void testContainsCharRangeNegatedVsNonNegatedAndFullRange() {
        CharRange negated = CharRange.isNotIn('d', 'f');   // everything except d-f
        CharRange outside = CharRange.isIn('a', 'c');      // entirely outside excluded block
        CharRange full = CharRange.isIn((char) 0, Character.MAX_VALUE);

        assertAll(
                () -> assertTrue(negated.contains(outside)),
                () -> assertTrue(full.contains(negated))
        );
    }
