import org.junit.Test;
import static org.junit.Assert.*;

public class ByteVectorTest {

    @Test
    public void testDefaultConstructorInitialCapacityAndLength() {
        ByteVector v = new ByteVector();
        assertEquals(64, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void testConstructorWithInitialSize() {
        ByteVector v = new ByteVector(3);
        assertEquals(3, v.data.length);
        assertEquals(0, v.length);
    }

    @Test
    public void testPutByteWritesAndReturnsThis() {
        ByteVector v = new ByteVector(2);
        ByteVector ret = v.putByte(0x7F);
        assertSame(v, ret);
        assertEquals((byte) 0x7F, v.data[0]);
    }

    @Test
    public void testPutByteIncrementsLength() {
        ByteVector v = new ByteVector(2);
        v.putByte(1).putByte(2);
        assertEquals(2, v.length);
        assertEquals((byte) 2, v.data[1]);
    }

    @Test
    public void testPutByteEnlargesWhenFull() {
        ByteVector v = new ByteVector(1);
        v.putByte(1).putByte(2);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void testPut11WritesTwoBytes() {
        ByteVector v = new ByteVector(2);
        ByteVector ret = v.put11(0x12, 0x34);
        assertSame(v, ret);
        assertEquals((byte) 0x34, v.data[1]);
    }

    @Test
    public void testPut11UpdatesLength() {
        ByteVector v = new ByteVector(4);
        v.put11(1, 2).putByte(3);
        assertEquals(3, v.length);
        assertEquals((byte) 3, v.data[2]);
    }

    @Test
    public void testPutShortBigEndian() {
        ByteVector v = new ByteVector(2);
        v.putShort(0x1234);
        assertEquals((byte) 0x12, v.data[0]);
        assertEquals((byte) 0x34, v.data[1]);
    }

    @Test
    public void testPutShortEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(1);
        v.putShort(0x0102);
        assertTrue(v.data.length >= 2);
        assertEquals(2, v.length);
    }

    @Test
    public void testPut12WritesByteAndShort() {
        ByteVector v = new ByteVector(3);
        v.put12(0xAB, 0x1234);
        assertEquals((byte) 0xAB, v.data[0]);
        assertEquals((byte) 0x34, v.data[2]);
    }

    @Test
    public void testPut12EnlargesWhenNeeded() {
        ByteVector v = new ByteVector(2);
        v.put12(1, 0x0203);
        assertTrue(v.data.length >= 3);
        assertEquals(3, v.length);
    }

    @Test
    public void testPutIntBigEndianBytes() {
        ByteVector v = new ByteVector(4);
        v.putInt(0x01020304);
        assertEquals((byte) 0x01, v.data[0]);
        assertEquals((byte) 0x04, v.data[3]);
    }

    @Test
    public void testPutIntEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(3);
        v.putInt(0x01020304);
        assertTrue(v.data.length >= 4);
        assertEquals(4, v.length);
    }

    @Test
    public void testPutLongBigEndianBytes() {
        ByteVector v = new ByteVector(8);
        v.putLong(0x0102030405060708L);
        assertEquals((byte) 0x01, v.data[0]);
        assertEquals((byte) 0x08, v.data[7]);
    }

    @Test
    public void testPutLongEnlargesWhenNeeded() {
        ByteVector v = new ByteVector(7);
        v.putLong(0x0L);
        assertTrue(v.data.length >= 8);
        assertEquals(8, v.length);
    }

    @Test
    public void testPutUTF8AsciiOptimisticPathWritesLengthAndBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("ABC");
        assertEquals((byte) 0x00, v.data[0]);
        assertEquals((byte) 'C', v.data[4]);
    }

    @Test
    public void testPutUTF8AsciiSetsVectorLength() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("A");
        assertEquals(3, v.length);
        assertEquals((byte) 'A', v.data[2]);
    }

    @Test
    public void testPutUTF8TwoByteCharacterEncodesAndUpdatesByteLengthHeader() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u00A2"); // CENT SIGN, 2-byte UTF-8
        assertEquals((byte) 0x00, v.data[0]);
        assertEquals((byte) 0x02, v.data[1]);
    }

    @Test
    public void testPutUTF8TwoByteCharacterEncodingBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u00A2"); // U+00A2 -> C2 A2
        assertEquals((byte) 0xC2, v.data[2]);
        assertEquals((byte) 0xA2, v.data[3]);
    }

    @Test
    public void testPutUTF8ThreeByteCharacterEncodesAndUpdatesByteLengthHeader() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u20AC"); // EURO SIGN, 3-byte UTF-8
        assertEquals((byte) 0x00, v.data[0]);
        assertEquals((byte) 0x03, v.data[1]);
    }

    @Test
    public void testPutUTF8ThreeByteCharacterEncodingBytes() {
        ByteVector v = new ByteVector(10);
        v.putUTF8("\u20AC"); // U+20AC -> E2 82 AC
        assertEquals((byte) 0xE2, v.data[2]);
        assertEquals((byte) 0xAC, v.data[4]);
    }

    @Test
    public void testPutUTF8EnlargesWhenNeeded() {
        ByteVector v = new ByteVector(2);
        v.putUTF8("A");
        assertTrue(v.data.length >= 3);
        assertEquals(3, v.length);
    }

    @Test
    public void testPutByteArrayCopiesBytes() {
        ByteVector v = new ByteVector(10);
        byte[] src = new byte[] { 9, 8, 7, 6 };
        v.putByteArray(src, 1, 2);
        assertEquals((byte) 8, v.data[0]);
        assertEquals((byte) 7, v.data[1]);
    }

    @Test
    public void testPutByteArrayNullInsertsZerosAndUpdatesLength() {
        ByteVector v = new ByteVector(10);
        v.putByteArray(null, 0, 3);
        assertEquals(3, v.length);
        assertEquals((byte) 0, v.data[2]);
    }

    @Test
    public void testPutByteArrayEnlargesWhenNeededAndPreservesExistingContent() {
        ByteVector v = new ByteVector(2);
        v.putByte(0x11);
        byte[] src = new byte[] { 1, 2, 3, 4 };
        v.putByteArray(src, 0, 4);
        assertEquals((byte) 0x11, v.data[0]);
        assertTrue(v.data.length >= 5);
    }

    @Test
    public void testMultipleWritesPreserveOrderAcrossEnlarge() {
        ByteVector v = new ByteVector(1);
        v.putByte(1);
        v.putInt(0x02030405);
        assertEquals(5, v.length);
        assertEquals((byte) 0x05, v.data[4]);
    }
}

public ByteVector putUTF8(final String s) {
    int charLength = s.length();
    int len = length;
    if (len + 2 + charLength > data.length) {
        enlarge(2 + charLength);
    }
    byte[] data = this.data;
    // optimistic algorithm: instead of computing the byte length and then
    // serializing the string (which requires two loops), we assume the byte
    // length is equal to char length (which is the most frequent case), and
    // we start serializing the string right away. During the serialization,
    // if we find that this assumption is wrong, we continue with the
    // general method.
    data[len++] = (byte) (charLength >>> 8);
    data[len++] = (byte) charLength;
    for (int i = 0; i < charLength; ++i) {
        char c = s.charAt(i);
        if (c >= '\001' && c <= '\177') {
            data[len++] = (byte) c;
        } else {
            int byteLength = i;
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
                if (c >= '\001' && c <= '\177') {
                    byteLength++;
                } else if (c > '\u07FF') {
                    byteLength += 3;
                } else {
                    byteLength += 2;
                }
            }
            data[length] = (byte) (byteLength >>> 8);
            data[length + 1] = (byte) byteLength;
            if (length + 2 + byteLength > data.length) {
                length = len;
                enlarge(2 + byteLength);
                data = this.data;
            }
            for (int j = i; j < charLength; ++j) {
                c = s.charAt(j);
                if (c >= '\001' && c <= '\177') {
                    data[len++] = (byte) c;
                } else if (c > '\u07FF') {
                    data[len++] = (byte) (0xE0 | c >> 12 & 0xF);
                    data[len++] = (byte) (0x80 | c >> 6 & 0x3F);
                    data[len++] = (byte) (0x80 | c & 0x3F);
                } else {
                    data[len++] = (byte) (0xC0 | c >> 6 & 0x1F);
                    data[len++] = (byte) (0x80 | c & 0x3F);
                }
            }
            break;
        }
    }
    length = len;
    return this;
}

